        lo_dict["height"] = height
    border = kwargs.pop("border", None)
    if border:
        lo_dict.update(
            {
                "border": "solid gray 1px",
                "margin": "1pt",
                "padding": "5pt",
            }
        )
    wgt_dict["layout"] = widgets.Layout(**lo_dict)
    style_dict = {}
    if desc_width:
        style_dict["description_width"] = desc_width
    if kwargs:
        style_dict.update(kwargs)
    if style_dict:
        wgt_dict["style"] = style_dict
    return wgt_dict

