    """Show secrets from currently configured Key Vault."""
    view_text = []
    if not _KEYVAULT:
        self.txt_viewer.value = "\n".join(
            [
                "Azure keyvault libraries not found.",
                "Please install 'azure_keyvault_secrets' and",
