def _exec_query_for_values(func, func_kwargs, func_params, parent_kwargs):
    """Execute `func` for value (scalar or iterable) inputs."""
    var_iter_params, simple_params = _check_var_params_require_iter(
        func_params, func_kwargs, **parent_kwargs
    )

    if not var_iter_params or var_iter_params.keys() == simple_params.keys():
        # If there are no iter params that are not in the simple_params
        # dict - we're only using list params - we're good to go
        return func(**simple_params, **func_kwargs)

    for param in var_iter_params:
        simple_params.pop(param, None)

    # Even if we have list params, we can't use both list params and per-row
    # iteration so ignore these and run queries per row
    row_results = []
    # zip the value lists into tuples
    for row in zip(*(var_iter_params.values())):
        # build a single-line dict of {param1: row_value1...}
        col_param_dict = {param: row[idx] for idx, param in enumerate(var_iter_params)}
        row_results.append(func(**simple_params, **col_param_dict, **func_kwargs))
    return pd.concat(row_results, ignore_index=True)

def call_data_query(**kwargs):
    """Call function handling input params in different formats."""
    func_kwargs = kwargs.copy()

    # The input is a DataFrame
    if "data" in kwargs:
        # If the input is a DF, we might be required to join
        join_type, left_on, right_on, j_ignore_case = get_join_params(func_kwargs)
        src_data = kwargs["data"] if join_type else None
        # Get the results of the query
        result_df = _exec_query_for_df(func, func_kwargs, func_params, kwargs)
        if join_type and isinstance(src_data, pd.DataFrame):
            if left_on and right_on:
                # If explicit join keys
                return join_result(
                    input_df=src_data,
                    result_df=result_df,
                    left_on=left_on,
                    right_on=right_on,
                    how=join_type,
                    ignore_case=j_ignore_case,
                ).drop(columns="src_row_index", errors="ignore")
            if "src_row_index" in result_df.columns:
                # Otherwise merge on index of source
                return src_data.merge(
                    result_df,
                    left_index=True,
                    right_on="src_row_index",
                    how=join_type,
                ).drop(columns="src_row_index", errors="ignore")

            warnings.warn(
                "Cannot do an index merge on this result set. "
                + "Please use an explicit column join using 'left_on' "
                + "and 'right_on' join columns."
            )
        return result_df.drop(columns="src_row_index", errors="ignore")
    # The inputs are some mix of simple values and/or iterables.
    return _exec_query_for_values(func, func_kwargs, func_params, kwargs)

def _check_valid_settings_for_input(input_value: Any, pivot_reg: PivotRegistration):
    """Check input against settings in `pivot_reg`."""
    # Must have one of these specified
    if not (pivot_reg.func_df_col_param_name or pivot_reg.func_input_value_arg):
        raise ValueError(
            "A value for one of 'func_df_col_param_name' ",
            "or 'func_input_value_arg' must be given",
        )
    # If the function accepts only value type and cannot iterate. Make sure
    # that the input_value is a simple value
    if pivot_reg.input_type == "value":
        if not pivot_reg.func_input_value_arg:
            raise ValueError("No value for pivot func input argument was given")
        if not pivot_reg.can_iterate and (
            isinstance(input_value, pd.DataFrame)
            or (
                # pylint: disable=isinstance-second-argument-not-valid-type
                isinstance(input_value, pd.DataFrame)
                and not isinstance(input_value, str)
                # pylint: enable=isinstance-second-argument-not-valid-type
            )
        ):
            raise ValueError(
                f"This function does not accept inputs of {type(input_value)}"
            )

def _last_instance_of_type(var_type: Type, namespace: Dict[str, Any]):
    """Return the most recently created instance of type in namespace."""
    matches = [var for _, var in namespace.items() if isinstance(var, var_type)]
    if matches:
        return matches[-1]
    return None

def _get_param_string(self) -> str:
    """Return text representation of keyword params."""
    pos_params = [
        f"'{param}'" if isinstance(param, str) else str(param)
        for param in self.pos_params
    ]
    params_str = [
        f"{p_name}='{p_val}'"
        for p_name, p_val in self.params.items()
        if isinstance(p_val, str)
    ]
    params_other = [
        f"{p_name}={p_val}"
        for p_name, p_val in self.params.items()
        if not isinstance(p_val, str)
    ]
    return ", ".join(pos_params + params_str + params_other)

def _get_pd_accessor_func(data, df_func):
    """Return the function accessor `df_func` for the DataFrame `df`."""
    acc_name = func_name = func = None
    if "." in df_func:
        acc_name, func_name = df_func.split(".")
        accessor = getattr(data, acc_name, None)
        if accessor:
            func = getattr(accessor, func_name, None)
    else:
        func = getattr(data, df_func, None)
    if func:
        # run the function with any additional args
        return func
    return None

def _get_non_ip_functions(ioc_type_supp, ti_lookup):
    """Get functions for non-IP IoC types."""
    ioc_queries = defaultdict(dict)
    for ioc in IOC_TYPES - {"ipv4", "ipv6"}:
        supporting_provs = [
            prov for prov, supp_types in ioc_type_supp.items() if ioc in supp_types
        ]
        _, func_name, func = _create_lookup_func(ti_lookup, ioc, ioc, supporting_provs)
        ioc_queries[ioc][func_name] = func
    return ioc_queries

def _get_supported_ioc_types(ti_lookup: TILookup) -> Dict[str, Set[str]]:
    return {
        ti_prov_name: set(ti_prov.supported_types) & IOC_TYPES
        for ti_prov_name, ti_prov in ti_lookup.loaded_providers.items()
    }

def init():
    """Load VT3 Pivots if vt library is available."""
    if VT3_AVAILABLE:
        add_pivot_functions()

def _create_pivots(api_scope: Union[str, VTAPIScope, None]):
    if api_scope is None:
        scope = _get_vt_api_scope()
    elif isinstance(api_scope, str):
        scope = enum_parse(VTAPIScope, api_scope) or VTAPIScope.PUBLIC
    else:
        scope = api_scope
    try:
        vt_client = VTLookupV3()
    except (ValueError, AttributeError):
        # Can't initialize VTLookup - don't add the pivot funcs
        return {}

    if not isinstance(scope, VTAPIScope):
        # pylint: disable=not-an-iterable
        scope_names = [f"{name.lower()}" for name in VTAPIScope.__members__]
        raise ValueError(
            f"Unknown API scope {api_scope}",
            f"Valid values are {', '.join(scope_names)}",
        )

    if scope == VTAPIScope.PRIVATE:
        scope = VTAPIScope.ALL
    ent_funcs = {}
    for entity, (vt_type, category) in PIVOT_ENTITY_CATS.items():
        ent_relations = (
            rel for rel, rel_scope in category.items() if rel_scope & scope
        )
        func_dict = {}
        for relationship in ent_relations:
            f_part = partial(
                _get_relationships,
                vt_client=vt_client,
                vt_type=vt_type,
                relationship=relationship,
            )
            f_part.__doc__ = _create_func_doc(entity, relationship)
            func_dict[relationship] = f_part
        ent_funcs[entity] = func_dict
    return ent_funcs

def _create_func_doc(entity, relationship):
    """Create the relationship docstring."""
    fmt_name = " ".join(rel.capitalize() for rel in relationship.split("_"))
    description = f"Lookup VirusTotal {fmt_name} for {entity}."
    return _FUNC_DOC.format(description=description)

def _get_relationships(vt_client, entity_id, vt_type, relationship):
    result_df = vt_client.lookup_ioc_relationships(
        observable=entity_id, vt_type=vt_type, relationship=relationship
    )
    return result_df.reset_index()

