    param_attrib_map: Dict[str, str],
    get_timespan: Callable[[], TimeSpan],

def wrapped_query_func(*args, **kwargs):
    """Wrap function to extract and map parameters."""
    # If time params not specified, add the global ones.
    time_params = {
        "start": kwargs.pop("start", get_timespan().start),
        "end": kwargs.pop("end", get_timespan().end),
    }
    # If this is an entity assume it's called as an instance method
    if args and isinstance(args[0], entities.Entity):
        value = args[0]
        param_dict = {
            param: getattr(value, attrib, None)
            for param, attrib in param_attrib_map.items()
            if hasattr(value, attrib)
        }
        return exec_query_func(**param_dict, **time_params, **kwargs)
    return exec_query_func(**time_params, **kwargs)

def __len__(self):
    """Return number of items in the attribute collection."""
    return len(self.__dict__)

def __iter__(self):
    """Return iterator over the attributes."""
    return iter(self.__dict__.items())

def __getattr__(self, name):
    """Print usable error message if attribute not found."""
    if "." in name:
        try:
            attr = _get_dot_attrib(self, name)
        except KeyError:
            pass
        else:
            return attr
    nm_err: Optional[Exception] = None
    try:
        # check for similar-named attributes in __dict__
        check_kwarg(name, list(self.__dict__.keys()))
    except NameError as err:
        nm_err = err
    if nm_err:
        raise AttributeError(
            f"{self.__class__.__name__} object has no attribute {name}"
        ) from nm_err
    raise AttributeError(
        f"{self.__class__.__name__} object has no attribute {name}"
    )

def _get_dot_attrib(obj, elem_path: str) -> Any:
    """Return attribute at dotted path."""
    path_elems = elem_path.split(".")
    cur_node = obj
    for elem in path_elems:
        cur_node = getattr(cur_node, elem, None)
        if cur_node is None:
            raise KeyError(f"{elem} value of {elem_path} is not a valid path")
    return cur_node

def __getattr__(self, attrib):
    """Return attribute from args if not in self."""
    if attrib in self.args:
        return self.args[attrib]
    raise AttributeError(f"Invalid attribute '{attrib}'")

