def check_version():
    """Check the current version against latest on PyPI."""
    installed_version = parse_version(__version__)

    # fetch package metadata from PyPI
    pypi_url = "https://pypi.org/pypi/msticpy/json"
    pkg_data = {"info": {"version": "0.0.0"}, "releases": {}}
    with contextlib.suppress(httpx.ConnectError):
        if not unit_testing():
            resp = httpx.get(
                pypi_url,
                timeout=httpx.Timeout(2.0, connect=2.0),
                headers=mp_ua_header(),
            )
            if resp.status_code == 200:
                pkg_data = resp.json()

    latest_version = pkg_data.get("info", {}).get("version", None)
    if latest_version:
        latest_version = parse_version(latest_version)
    elif "releases" in pkg_data:
        latest_version = max(parse_version(s) for s in pkg_data["releases"].keys())

    print(
        "msticpy version",
        "installed:",
        installed_version,
        "latest published:",
        latest_version if str(latest_version) != "0.0.0" else "unknown",
    )
    if installed_version < latest_version:
        print(f"A newer version of msticpy - {latest_version} is available.")
        print("Upgrade with 'pip install --upgrade msticpy'")
    else:
        print("Latest known version is installed.")

def _parse_time(time_val, prop_name):
    if time_val is None:
        return None
    if isinstance(time_val, datetime):
        return time_val
    with contextlib.suppress(ValueError, ParserError):
        if isinstance(time_val, str):
            return pd.to_datetime(time_val)
    raise ValueError(f"'{prop_name}' must be a datetime or a datetime string.")

def _parse_timedelta(time_val):
    if time_val is None:
        return None
    if isinstance(time_val, timedelta):
        return time_val
    with contextlib.suppress(ValueError, ParserError):
        if isinstance(time_val, str):
            return pd.Timedelta(time_val).to_pytimedelta()
    raise ValueError(
        "'period' must be a pandas-compatible time period string",
        " or Python timedelta.",
    )

def __eq__(self, value):
    """Return True if the timespans are equal."""
    return (
        self.start == value.start and self.end == value.end
        if isinstance(value, TimeSpan)
        else False
    )

def __hash__(self):
    """Return the hash of the timespan."""
    return hash((self.start, self.end))

def __repr__(self):
    """Return repr string."""
    return (
        f"{self.__class__.__name__}"
        f"(start={self.start}, end={self.end}, period={self.period})"
    )

def default_before_after(default: Optional[int], unit: TimeUnit) -> int:
    """Return default before and after bounds for a TimeUnit."""
    if default is not None:
        return abs(default)
    if unit in (TimeUnit.DAY, TimeUnit.WEEK):
        return 1
    if unit == TimeUnit.HOUR:
        return 6
    return 60

def _get_time_parameters(self, **kwargs):
    """Process different init time parameters from kwargs."""
    timespan: TimeSpan = kwargs.pop("timespan", None)
    start = kwargs.pop("start", None)
    end = kwargs.pop("end", None)
    if timespan:
        self._query_end = self.origin_time = timespan.end
        self._query_start = timespan.start
    elif start and end:
        timespan = TimeSpan(start=start, end=end)
        self._query_start = timespan.start
        self._query_end = self.origin_time = timespan.end
    else:
        self.before = default_before_after(self.before, self._time_unit)
        self.after = default_before_after(self.after, self._time_unit)
        # Calculate time offsets from origin
        self._query_start = self.origin_time - timedelta(
            0, self.before * self._time_unit.value
        )
        self._query_end = self.origin_time + timedelta(
            0, self.after * self._time_unit.value
        )
    if "units" not in kwargs:
        self._infer_time_units()
    if self.after is None:
        self.after = 0
    if self.before is None:
        self.before = int(
            (self._query_end - self._query_start).total_seconds()
            / self._time_unit.value
        )

def _infer_time_units(self):
    """Infer reasonable time unit from current timespan."""
    # If time units not set explicitly, set to something sensible,
    # based on start/end times
    if abs(self.timespan.period.days) > 1:
        self._time_unit = TimeUnit.DAY
    elif abs(self.timespan.period.total_seconds()) > 3600:
        self._time_unit = TimeUnit.HOUR
    else:
        self._time_unit = TimeUnit.MINUTE

def _process_args(*args, timespan, start, end, period):
    # Allow for use with unnamed arguments
    if len(args) == 1:
        timespan = args[0]  # e.g. a tuple of start, end
    if len(args) == 2:
        start = args[0]
        if isinstance(args[1], (str, datetime)):
            end = args[1]
        elif isinstance(args[1], Number):
            period = args[1]
    if timespan:
        if _is_timespan_type(timespan):
            start = start or getattr(timespan, "start", None)
            end = end or getattr(timespan, "end", None)
            period = period or getattr(timespan, "period", None)
        elif isinstance(timespan, tuple):
            start = timespan[0]
            end = timespan[1]

    return start, end, period

def _is_timespan_type(timespan):
    """Return true if the object has least 2 usable properties."""
    return (
        sum(
            [
                hasattr(timespan, "start"),
                hasattr(timespan, "end"),
                hasattr(timespan, "period"),
            ]
        )
        >= 2
    )

def _read_config_values(file_path: str) -> Dict[str, str]:
    """Read configuration file."""
    if not file_path:
        return {}
    with contextlib.suppress(json.JSONDecodeError):
        with open(file_path, "r", encoding="utf-8") as json_file:
            if json_file:
                return json.load(json_file)
    return {}

def _search_for_file(self, pattern: str) -> Optional[str]:
    config_file = None
    for start_path in (".", ".."):
        searched_configs = list(Path(start_path).glob(pattern))
        for found_file in searched_configs:
            if found_file.name == "msticpyconfig.yaml":
                config_file = str(found_file)
                break
            test_content = self._read_config_values(str(found_file))
            if "workspace_id" in test_content:
                config_file = str(found_file)
                break
        if config_file:
            break
    if config_file:
        # Warn that we're using a "found" file, not one in the current directory
        print("Warning")
        print("\n".join(_NO_CONFIG_WARN).format(config_file=config_file))
    return config_file

