def from_connection_string(cls, connection_str: str) -> "WorkspaceConfig":
    """Create a WorkstationConfig from a connection string."""
    tenant_regex = r"""
    .*tenant\s?=\s?['\"]\{?
    (?P<tenant_id>[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})
    \}?['\"].*"""
    workspace_regex = r"""
    .*workspace\s?=\s?['\"]\{?
    (?P<workspace_id>[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})
    \}?['\"].*"""
    ws_name_regex = r".*alias\s?=\s?['\"]\{?(?P<workspace_name>\w+)['\"].*"

    tenant_id = workspace_id = workspace_name = None
    if match := re.match(tenant_regex, connection_str, re.IGNORECASE | re.VERBOSE):
        tenant_id = match.groupdict()["tenant_id"]
    else:
        raise ValueError("Could not find tenant ID in connection string.")
    if match := re.match(
        workspace_regex, connection_str, re.IGNORECASE | re.VERBOSE
    ):
        workspace_id = match.groupdict()["workspace_id"]
    else:
        raise ValueError("Could not find workspace ID in connection string.")
    if match := re.match(ws_name_regex, connection_str, re.IGNORECASE | re.VERBOSE):
        workspace_name = match.groupdict()["workspace_name"]
    return cls(
        config={
            cls.CONF_WS_ID_KEY: workspace_id,  # type: ignore[dict-item]
            cls.CONF_TENANT_ID_KEY: tenant_id,  # type: ignore[dict-item]
            cls.CONF_WS_NAME_KEY: workspace_name,  # type: ignore[dict-item]
        }
    )

def list_workspaces(cls) -> Dict:
    """
    Return list of available workspaces.

    Returns
    -------
    Dict
        Dictionary of workspaces with workspace and tenantIds.

    """
    ws_settings = get_config("AzureSentinel", {}).get("Workspaces")
    return (
        {
            ws_name: {
                cls.PKG_CONF_WS_KEY: ws.get(cls.PKG_CONF_WS_KEY),
                cls.PKG_CONF_TENANT_KEY: ws.get(cls.PKG_CONF_TENANT_KEY),
            }
            for ws_name, ws in ws_settings.items()
        }
        if ws_settings
        else {}
    )

def parse_resource_id(res_id: str) -> Dict[str, Any]:
    """Extract components from workspace resource ID."""
    res_id_parts = res_id.split("/")
    return {
        "subscription_id": res_id_parts[1] if len(res_id_parts) > 1 else None,
        "resource_group": res_id_parts[3] if len(res_id_parts) > 3 else None,
        "workspace_name": res_id_parts[7] if len(res_id_parts) > 7 else None,
    }

def _read_pkg_config_values(self, workspace_name: Optional[str] = None):
    """Try to find a usable config from the MSTICPy config file."""
    ws_settings = get_config("AzureSentinel", {}).get("Workspaces")  # type: ignore
    if not ws_settings:
        return
    selected_workspace: Dict[str, str] = {}
    if workspace_name:
        selected_workspace = self._lookup_ws_name_and_id(
            workspace_name, ws_settings
        )
    elif "Default" in ws_settings:
        selected_workspace = ws_settings["Default"]
    elif len(ws_settings) == 1:
        selected_workspace = next(iter(ws_settings.values()))

    if selected_workspace:
        self._config = {}
        for name, value in selected_workspace.items():
            tgt_name = self._SETTINGS_TO_CONFIG_NAME_MAP.get(name)
            if tgt_name and value:
                self._config[tgt_name] = value

def _lookup_ws_name_and_id(self, ws_name: str, ws_configs: dict):
    for name, ws_config in ws_configs.items():
        if ws_name.casefold() == name.casefold():
            return ws_config
        if ws_config.get(self.PKG_CONF_WS_KEY, "").casefold() == ws_name.casefold():
            return ws_config
        if (
            ws_config.get(self.PKG_CONF_NAME_KEY, "").casefold()
            == ws_name.casefold()
        ):
            return ws_config
    return {}

def __getitem__(self, key):
    """Return key value via SecretsClient.read_secret."""
    if key not in self.data:
        raise KeyError(key)
    if _SECRETS_ENABLED:
        return SecretsClient.read_secret(self.data[key])
    return self.data[key]

def _get_secret_func(self, secret_name: str, vault_name: str) -> Callable[[], Any]:
    """Return a func to access a secret."""
    if self._use_keyring and self._keyring_client.get_secret(secret_name):
        return self._create_secret_func(self._keyring_client, secret_name)

    # If the secret is not in keyring, get the vault holding this secret
    if not self.kv_secret_vault.get(secret_name):
        self._add_key_vault(secret_name=secret_name, vault_name=vault_name)

    vault = self.kv_vaults[vault_name]
    if self._use_keyring:
        # store the secret in keyring and return an accessor
        # to the keyring value.
        self._keyring_client.set_secret(secret_name, vault.get_secret(secret_name))
        return self._create_secret_func(self._keyring_client, secret_name)
    # if not using Keyring - return a KeyVault accessor
    return self._create_secret_func(vault, secret_name)

def refresh_keyring():
    """Refresh local keyring secrets cache from Key Vault."""
    if _secrets_enabled():
        _SECRETS_CLIENT.refresh_keyring()

def clear_keyring():
    """Delete local keyring secrets cache."""
    if _secrets_enabled():
        _SECRETS_CLIENT.clear_keyring_secrets()

def refresh_keyring(self):
    """Reload keyring values from Key Vault."""
    if not self._use_keyring or not self._keyring_client.is_keyring_available():
        return
    for kv_client in self.kv_vaults.values():
        for secret_name in kv_client.secrets:
            if not self._keyring_client.get_secret(secret_name):
                continue
            self._keyring_client.set_secret(
                secret_name=secret_name,
                secret_value=kv_client.get_secret(secret_name),
            )

def clear_keyring_secrets(self):
    """Clear any cached secrets from keyring."""
    if not self._use_keyring or not self._keyring_client.is_keyring_available():
        return
    for kv_client in self.kv_vaults.values():
        for secret_name in kv_client.secrets:
            if not self._keyring_client.get_secret(secret_name):
                continue
            self._keyring_client.delete_secret(secret_name=secret_name)

