def init_getattr(module_name: str, dynamic_imports: Dict[str, str], attrib: str):
    """Import and return dynamic attribute."""
    if attrib in dynamic_imports:
        module = importlib.import_module(dynamic_imports[attrib])
        return getattr(module, attrib)
    raise AttributeError(f"{module_name} has no attribute {attrib}")

def __getattr__(attrib: str):
    """Import and a dynamic attribute of module."""
    return init_getattr(__name__, _DEFAULT_IMPORTS, attrib)

def lazy_import(module: str, attrib: str, call: bool = False):
    """Import attribute from module on demand."""
    attribute = None

    def import_item(*args, **kwargs):
        """Return the attribute, importing module if needed."""
        nonlocal attribute
        if attribute is None:
            imp_module = importlib.import_module(module)
            attribute = getattr(imp_module, attrib)
        return (
            attribute(*args, **kwargs) if (call and callable(attribute)) else attribute
        )

    return import_item

def import_item(*args, **kwargs):
    """Return the attribute, importing module if needed."""
    nonlocal attribute
    if attribute is None:
        imp_module = importlib.import_module(module)
        attribute = getattr(imp_module, attrib)
    return (
        attribute(*args, **kwargs) if (call and callable(attribute)) else attribute
    )

def _hash_ip_item(ip_addr: str) -> str:
    """
    Hash IP address.

    Parameters
    ----------
    ip_addr : str
        IP address string

    Returns
    -------
    str
        Hashed IP Address.

    """
    if not ip_addr or not isinstance(ip_addr, str):
        return ip_addr
    if "." in ip_addr:
        return _map_ip4_address(ip_addr)
    if ":" in ip_addr:
        if ip_addr.strip() == "::1":
            # Localhost
            return ip_addr
        ip_out = []
        for part in ip_addr.split(":"):
            enc = hashlib.sha256(bytes(part, "utf-8")).hexdigest()[: len(part)]
            ip_out.append(enc)
        return ":".join(ip_out)
    return hashlib.sha256(bytes(ip_addr, "utf-8")).hexdigest()[: len(ip_addr)]

def _map_ip4_address(ip_addr: str) -> str:
    try:
        ip_bytes = [int(byte) for byte in ip_addr.split(".")]
    except ValueError:
        return hash_string(ip_addr)
    if ".".join(str(byte) for byte in ip_bytes) in _WK_IPV4:
        # Well-known address
        return ip_addr
    if ip_bytes[0] == 10:
        # class A res private
        ls_bytes = ".".join(
            [
                ip_map[idx].get(byte, "1")
                for idx, byte in enumerate(ip_addr.split(".")[1:])
            ]
        )
        return f"10.{ls_bytes}"
    if ip_bytes[0] == 17 and (16 <= ip_bytes[1] <= 31):
        # class B res private
        ls_bytes = ".".join(
            [
                ip_map[idx].get(byte, "1")
                for idx, byte in enumerate(ip_addr.split(".")[2:])
            ]
        )
        return f"{ip_bytes[0]}.{ip_bytes[1]}.{ls_bytes}"
    if ip_bytes[0] == 192 and ip_bytes[1] == 168:
        # class C res private
        ls_bytes = ".".join(
            [
                ip_map[idx].get(byte, "1")
                for idx, byte in enumerate(ip_addr.split(".")[2:])
            ]
        )
        return f"192.168.{ls_bytes}"
    # by default, remap all
    return ".".join(
        [ip_map[idx].get(byte, "1") for idx, byte in enumerate(ip_addr.split("."))]
    )

def sql_to_kql(sql: str, target_tables: Dict[str, str] = None) -> str:
    """Parse SQL and return KQL equivalent."""
    # ensure literals are surrounded by single quotes
    sql = _single_quote_strings(sql)

    # replace table names
    if target_tables:
        for table in target_tables:
            sql = sql.replace(table, target_tables[table])
    # replace keywords
    # sql = _remap_kewords(sql)
    parsed_sql = parse(sql)
    query_lines = _parse_query(parsed_sql)
    return "\n".join(line for line in query_lines if line.strip())

def _single_quote_strings(sql: str) -> str:
    """Replace unquoted double-quotes with single-quotes."""
    return re.sub(r"(?<![\\])\"", "'", sql)

def _parse_query(parsed_sql: Dict[str, Any]) -> List[str]:  # noqa: MC0001
    """Translate query or subquery."""
    query_lines: List[str] = []
    if isinstance(parsed_sql, str):
        return [parsed_sql]
    if FROM in parsed_sql:
        _process_from(parsed_sql[FROM], query_lines)
    if WHERE in parsed_sql:
        query_lines.append(f"| where {_parse_expression(parsed_sql[WHERE])}")

    if GROUP_BY in parsed_sql:
        _process_group_by(parsed_sql, query_lines)
        # Get rid of the SELECT statement since we've processed it in
        # the groupby
        parsed_sql.pop(SELECT, parsed_sql.pop(SELECT_DISTINCT, None))

    distinct_select: List[Dict[str, Any]] = []
    if SELECT_DISTINCT in parsed_sql:
        distinct_select.extend(parsed_sql[SELECT_DISTINCT])
        _process_select(
            parsed_sql[SELECT_DISTINCT], parsed_sql[SELECT_DISTINCT], query_lines
        )
    if SELECT in parsed_sql:
        _process_select(parsed_sql[SELECT], parsed_sql[SELECT], query_lines)
    if ORDER_BY in parsed_sql:
        query_lines.append(f"| order by {_create_order_by(parsed_sql[ORDER_BY])}")
    if distinct_select:
        query_lines.append(
            f"| distinct {', '.join(_create_distinct_list(distinct_select))}"
        )
    if LIMIT in parsed_sql:
        query_lines.append(f"| limit {parsed_sql[LIMIT]}")
    if UNION in parsed_sql:
        union_subquery = {UNION_ALL: parsed_sql[UNION]}
        query_lines.extend(_parse_query(union_subquery))
        query_lines.append("| distinct *")
    if UNION_ALL in parsed_sql:
        union_l_expr = "\n".join(_parse_query(parsed_sql[UNION_ALL][0]))
        query_lines.append(union_l_expr)
        union_r_expr = "\n  ".join(_parse_query(parsed_sql[UNION_ALL][1]))
        query_lines.append(f"| union ({union_r_expr}\n)")

    return query_lines

def _get_expr_list(expr_list):
    if (
        isinstance(expr_list, list)
        and len(expr_list) == 1
        and isinstance(expr_list[0], dict)
        and isinstance(expr_list[0].get("value"), list)
    ):
        return expr_list[0]["value"]
    return expr_list

def _get_expr_value(expr_val):
    if isinstance(expr_val, dict) and "value" in expr_val:
        return expr_val["value"]
    if isinstance(expr_val, list):
        return _get_expr_list(expr_val)
    return expr_val

def _process_group_by(parsed_sql: Dict[str, Any], query_lines: List[str]):
    """Process GROUP BY clause."""
    group_by_expr = parsed_sql[GROUP_BY]
    group_by_expr = (
        group_by_expr if isinstance(group_by_expr, list) else [group_by_expr]
    )
    by_clause = ", ".join(val["value"] for val in group_by_expr if val.get("value"))

    expr_list = parsed_sql.get(SELECT, parsed_sql.get(SELECT_DISTINCT, []))
    group_by_expr_list = []
    expr_list = _get_expr_value(expr_list)
    for expr in expr_list:
        name_expr = ""
        if "name" in expr:
            name_expr = f"{expr.get('name')} = "
        if isinstance(expr.get("value"), str):
            group_by_expr_list.append(f"{name_expr}any({expr['value']})")
        else:
            group_by_expr_list.append(
                f"{name_expr}{_parse_expression(expr.get('value'))}"
            )
    query_lines.append(f"| summarize {', '.join(group_by_expr_list)} by {by_clause}")

def _parse_expression(expression):  # noqa: MC0001
    """Return parsed expression."""
    if _is_literal(expression)[0]:
        return _quote_literal(expression)
    if not isinstance(expression, dict):
        return expression
    if AND in expression:
        return "\n  and ".join(
            [f"({_parse_expression(expr)})" for expr in expression[AND]]
        )
    if OR in expression:
        return "\n  or ".join(
            [f"({_parse_expression(expr)})" for expr in expression[OR]]
        )
    if NOT in expression:
        return f" not ({_parse_expression(expression[NOT])})"
    if BETWEEN in expression:
        args = expression[BETWEEN]
        betw_expr = f"{_parse_expression(args[1])} .. {_parse_expression(args[2])}"
        return f"{args[0]} between ({betw_expr})"
    if NOT_BETWEEN in expression:
        args = expression[NOT_BETWEEN]
        betw_expr = f"{_parse_expression(args[1])} .. {_parse_expression(args[2])}"
        return f"{args[0]} !between ({betw_expr})"
    if IN in expression or NOT_IN in expression:
        sql_op = IN if IN in expression else NOT_IN
        kql_op = IN if IN in expression else "!in"
        args = expression[sql_op]

        right = _quote_literal(args[1])
        if isinstance(right, list):
            _db_print(args[1])
            arg_list = ", ".join([str(_parse_expression(l_item)) for l_item in right])
            return f"{args[0]} {kql_op} ({arg_list})"
        sub_query = "\n".join(_parse_query(right))
        return f"{args[0]} {kql_op} ({sub_query})"

    # Handle other operators
    oper = next(iter(expression.keys())) if expression else None
    if oper in BINARY_OPS:
        right = _parse_expression(expression[oper][1])
        left = _parse_expression(expression[oper][0])
        return f"{left} {BINARY_OPS[oper]} {right}"
    if LIKE in expression:
        return _process_like(expression)

    # For everything else, assume it's a function
    if expression:
        func, operand = next(iter(expression.items()))
        #         set_trace()
        if isinstance(operand, list):
            return _map_func(func, *operand)
        return _map_func(func, operand)
    return "EXPRESSION {expression} not resolved."

def _rewrite_table_refs(join_expr: Union[Any, str, List], table_expr: str) -> str:
    """Rewrite dotted prefixes."""
    p_expr = _parse_expression(join_expr)
    prefixes = set(re.findall(r"(\w+)\.", p_expr))
    if not prefixes:
        return p_expr
    if f"{table_expr}" in prefixes:
        p_expr = p_expr.replace(f"{table_expr}.", "$right.")
        prefixes.remove(f"{table_expr}")
    for prefix in prefixes:
        p_expr = p_expr.replace(
            f"{prefix}.",
            "$right." if prefix.casefold() == table_expr.casefold() else "$left.",
        )
    return p_expr

def _create_distinct_list(distinct_select):
    distinct_list = []
    for distinct_item in distinct_select:
        if "name" in distinct_item:
            distinct_list.append(distinct_item["name"])
        else:
            val = _parse_expression(_get_expr_value(distinct_item))
            if val != distinct_item.get("value"):
                # If value was a complex expression we can't use
                # it directly so just revert to distinct *
                distinct_list = ["*"]
                break
            distinct_list.append(val)
    return distinct_list

def _db_print(*args, **kwargs):
    if _DEBUG:
        print(*args, **kwargs)

def _map_func(func: str, *args) -> str:
    """Return KQL function for SQL function."""
    func = func.lower().strip()
    args_dict = {f"p{idx}": arg for idx, arg in enumerate(args)}
    def_arg_fmt = ", ".join(f"{{{arg}}}" for arg in args_dict)
    if func not in SQL_KQL_FUNC_MAP:
        func_fmt = f"{func}({def_arg_fmt}) // WARNING unmapped function\n"
        return func_fmt.format(**args_dict)
    func_map = SQL_KQL_FUNC_MAP[func]

    if (
        func == "count"
        and isinstance(args[0], dict)
        and next(iter(args[0])) == "distinct"
    ):
        func_arg = _get_expr_value(args[0]["distinct"])
        return f"dcount({func_arg})"

    if not func_map.cust_arg_fmt and not func_map.cust_func_format:
        func_fmt = f"{func_map.default}({def_arg_fmt})"
        return func_fmt.format(**args_dict)
    if func_map.cust_arg_fmt:
        func_fmt = f"{func_map.default}({func_map.cust_arg_fmt})"
        return func_fmt.format(**args_dict)
    if func_map.cust_func_format:
        func_fmt = f"{func_map.cust_func_format}"
        return func_fmt.format(**args_dict)
    raise ValueError(f"Could not map function or args {func}{args_dict}")

def default(self, o):
    if isinstance(o, Entity):
        return {
            name: value
            for name, value in o.properties.items()
            if value and name != "edges"
        }
    # Let the base class default method raise the TypeError
    return json.JSONEncoder.default(self, o)

def blank_schema_dict(cls) -> Dict[str, Any]:
    """Return blank schema dictionary."""
    return {
        field: "required"
        if (attrib.default or attrib.default == attr.NOTHING)
        else None
        for field, attrib in attr.fields_dict(cls).items()
    }

def _quote_literal(expr: Union[str, List[str], Any]) -> Any:
    """Quote string if it is a literal."""
    literal, expr = _is_literal(expr)
    if not literal:
        return expr
    if isinstance(expr, str):
        return _quote(expr)
    if isinstance(expr, list):
        return [_quote(memb) for memb in expr]
    return expr

def _is_literal(expr: Union[Dict[str, Any], Any]) -> Tuple[bool, Any]:
    """Check if literal string."""
    if isinstance(expr, dict) and "literal" in expr:
        return True, expr["literal"]
    return False, expr

def _quote(expr: str) -> str:
    """Quote a string, if not already quoted."""
    if expr.startswith("'") and expr.endswith("'"):
        return expr
    return f"'{expr}'"

def _process_like(expression: Dict[str, Any]) -> str:
    """Process Like clause."""
    left = _parse_expression((expression[LIKE][0]))
    literal, right = _is_literal(expression[LIKE][1])
    if not (literal and isinstance(right, str)):
        raise ValueError(
            f"Right side operand {right} isn't usable in LIKE expression",
            f"{left} LIKE {right}",
        )
    if re.match("^[^%_]+[%_]$", right):
        oper = "startswith"
        right = right.replace("%", "").replace("_", "")
    elif re.match("^[%_][^%_]+$", right):
        oper = "endswith"
        right = right.replace("%", "").replace("_", "")
    elif re.match("^[%_][^%_]+[%_]$", right):
        oper = "contains"
        right = right.replace("%", "").replace("_", "")
    else:
        oper = "matches regex"
        right = right.replace("_", ".").replace("%", ".*")
    right = _quote(right)
    return f"{left} {oper} {right}"

def _get_join_list(parsed_sql: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    """Return list of JOIN sub-expressions."""
    if not isinstance(parsed_sql, list):
        return []
    join_list = []
    for from_source in parsed_sql:
        if not isinstance(from_source, dict):
            continue
        join = JOIN_KEYWORDS & from_source.keys()
        if join:
            join_list.append(from_source)
    return join_list

def query_with_results(self, query, **kwargs):
    """Return query with fake results."""
    return self.query(query, **kwargs), "OK"

def value(self, value: Union[str, Dict[str, Optional[str]]]):
    """Set value of controls from dict."""
    if isinstance(value, dict):
        self._set_ctrl_from_val(path="", value=value)

def _set_ctrl_from_val(self, path, value):
    if value is None:
        return
    for key, val in value.items():
        sub_path = f"{path}.{key}" if path else key
        if isinstance(val, dict):
            if isinstance(self.controls[key], widgets.Textarea):
                self.controls[key].value = py_to_widget(
                    val, ctrl=self.controls[key]
                )
            else:
                self._set_ctrl_from_val(sub_path, val)
        elif key in self.controls:
            self.controls[key].value = py_to_widget(val, ctrl=self.controls[key])

def _replace_query_macros(self):
    """Replace any macro strings in the query with substitutions."""
    replace_keys = re.findall(r"\$\<([^>]+)\>\$?", self._query)
    if not replace_keys:
        return
    replace_values = {}
    if "query_macros" in self._source:
        replace_values = {
            name: properties.get("value", "")
            for name, properties in self["query_macros"].items()
        }
    for key in replace_keys:
        if key in replace_keys:
            replacement = replace_values.get(key, "")
            self._query = self._query.replace(f"$<{key}>$", replacement)
    self._query = re.sub("\n{2,}", "\n", self._query)

def create_doc_string(self) -> str:
    """
    Return a doc string for the query.

    Returns
    -------
    str
        New-line delimited docstring dynamically
        created from query definition properties.

    """
    param_block = ["Parameters", "----------"]
    for p_name, p_props in sorted(self.params.items()):
        if "default" in p_props:
            optional = " (optional)"
            def_value = p_props["default"]
            if isinstance(def_value, str) and len(def_value) > 50:
                def_value = f"{def_value[:50]}..."
        else:
            optional = ""
            def_value = None
        param_block.extend(
            (
                f'{p_name}: {p_props.get("type", "Any")}{optional}',
                f'    {p_props.get("description", "no description")}',
            )
        )

        if def_value:
            param_block.append(f"    (default value is: {def_value})")
        if "aliases" in p_props:
            aliases = p_props["aliases"]
            if isinstance(aliases, str):
                aliases = [aliases]
            alias_list = ", ".join(f"'{alias}'" for alias in aliases)
            param_block.append(f"    Aliases: {alias_list}")
    doc_string = [f"{self.description}", ""]
    return "\n".join(doc_string + param_block)

def _parse_param_list(param_value: Union[str, List]) -> List[Any]:
    """Parse list, comma-delim str or str."""
    if isinstance(param_value, list):
        return param_value
    if isinstance(param_value, str) and "," in param_value:
        return [item.strip() for item in param_value.split(",")]
    return [param_value]

def _format_parameter(self, p_name, param_dict, param_settings, formatters):
    # The parameter may need custom formatting
    fmt_template = param_settings.get("format", None)
    if fmt_template:
        # custom formatting template in the query definition
        param_dict[p_name] = fmt_template.format(param_dict[p_name])
    elif param_settings["type"] == "datetime" and isinstance(
        param_dict[p_name], datetime
    ):
        # format datetime using driver formatter or default formatter
        if formatters and Formatters.DATETIME in formatters:
            param_dict[p_name] = formatters[Formatters.DATETIME](param_dict[p_name])
        else:
            param_dict[p_name] = self._format_datetime_default(param_dict[p_name])
    elif param_settings["type"] == "list":
        # format list using driver formatter or default formatter
        if formatters and Formatters.LIST in formatters:
            param_dict[p_name] = formatters[Formatters.LIST](param_dict[p_name])
        else:
            param_dict[p_name] = self._format_list_default(param_dict[p_name])

def _format_list_default(item_list: List[Any]) -> str:
    """Return formatted list parameter."""
    fmt_list = []
    for item in item_list:
        if isinstance(item, str):
            fmt_list.append(f"'{item}'")
        else:
            fmt_list.append(f"{item}")
    return ", ".join(fmt_list)

def _convert_datetime(self, param_value: Any) -> datetime:
    if isinstance(param_value, datetime):
        return param_value
    if isinstance(param_value, Number):
        # datetime specified as a number - we
        # interpret this as an offset from utcnow
        return datetime.now(tz=timezone.utc) + timedelta(  # type: ignore
            param_value  # type: ignore
        )
    try:
        # If this is a simple integer we want to catch it before sending
        # it to dateutil parser since this does the wrong thing with it.
        int(param_value)
        return self._calc_timeoffset(str(param_value))
    except ValueError:
        pass
    try:
        # Try to parse datetime with dateutil parser
        return parse(param_value)
    except ParserError:
        # If none of these, assume a time delta
        return self._calc_timeoffset(str(param_value))

def _format_datetime(date_time: datetime) -> str:
    """Return datetime-formatted string."""
    return date_time.isoformat(sep="T") + "Z"

def _get_time_params(self, **kwargs):
    if "days" in kwargs:
        end = datetime.now()
        start = end - timedelta(days=kwargs["days"])
        return self._format_datetime(start), self._format_datetime(end)

    start = kwargs.pop("start", kwargs.pop("start_time", None))
    end = kwargs.pop("end", kwargs.pop("end_time", None))
    if start and not end:
        end = datetime.now()
    elif not start:
        raise MsticpyUserError(
            "Error! requires either 'days' or 'start' parameters",
            title="Missing parameter.",
            help_uri=_HELP_URI,
            notebook_uri=_SL_NB_URI,
        )
    return self._format_datetime(start), self._format_datetime(end)

def _format_datetime(date_time: datetime) -> str:
    """Return datetime-formatted string."""
    return date_time.strftime("%Y-%m-%dT%H:%M:%S")

def _to_datetime_utc_str(date_time):
    """Convert datetime to ISO date string."""
    if not isinstance(date_time, datetime):
        return date_time
    dt_str = date_time.isoformat()
    return dt_str.replace("+00:00", "Z") if "+00:00" in dt_str else f"{dt_str}Z"

def resolve_param_aliases(self, param_dict: Dict[str, Any]) -> Dict[str, Any]:
    """Try to resolve any parameters in `param_dict` that are aliases."""
    out_dict = {}
    for param, value in param_dict.items():
        if param in self.params:
            out_dict[param] = value
        else:
            aliased_param = self._get_aliased_param(param)
            if aliased_param:
                out_dict[aliased_param] = value
            else:
                out_dict[param] = value
    return out_dict

def _get_aliased_param(self, alias: str) -> Optional[str]:
    """Return first parameter with a matching alias."""
    aliased_params = {
        p_name: p_prop
        for p_name, p_prop in self.params.items()
        if "aliases" in p_prop
    }
    return next(
        (
            param
            for param, props in aliased_params.items()
            if alias in props["aliases"]
        ),
        None,
    )

def validate(self) -> Tuple[bool, List[str]]:
    """
    Validate the source to ensure that all required properties are present.

    Returns
    -------
    bool
        True if validation is successful.

    """
    req_source_items = {"args"}
    # match items surrounded by single {} but not double
    param_pattern = r"{(?<!{{)(?!{)([^}]+)}(?!})(?<!}})"

    valid_failures = []

    # Need req_source_items AND query item to be present
    source_props = self._source.keys() | self.defaults.keys()
    if not req_source_items.issubset(source_props):
        msg = (
            f"Source {self.name} does not have all required "
            + f"elements: {req_source_items - source_props}"
        )
        valid_failures.append(msg)
    if not self._query:
        msg = (
            f'Source {self.name} does not have "query" property '
            + "in args element."
        )
        valid_failures.append(msg)

    # Now get the query and the parameter definitions from the source and
    # check that every parameter specified in the query has a corresponding
    # 'parameter definition in either the source or the defaults.
    source_params = self.params.keys()
    try:
        data = json.loads(self._query)
        q_params = {
            value
            for line in json.dumps(data, indent=2).split("\n")
            for value in set(re.findall(param_pattern, line))
        }
    except JSONDecodeError:
        q_params = set(re.findall(param_pattern, self._query))

    missing_params = q_params - source_params
    if missing_params:
        msg = (
            f"Source {self.name} has parameters that are defined in "
            + "the query but not included in either defaults or "
            + "query-specific parameters element(s)\n"
            + f"Missing parameters are {missing_params}"
        )
        valid_failures.append(msg)

    missing_types = {
        p_name for p_name, p_props in self.params.items() if "type" not in p_props
    }
    if missing_types:
        msg = (
            f"Source {self.name} has parameters that are defined in "
            + 'the query but do not have a valid "type" property\n'
            + f"Parameters with missing types are {missing_types}"
        )
        valid_failures.append(msg)
    return (not valid_failures, valid_failures)

