def _valid_cache(path: Path, expired_days=30):
    """Return True if the file exists and is younger than `expired_days`."""
    if not path.is_file():
        return False
    days_old = (datetime.now() - datetime.fromtimestamp(path.stat().st_mtime)).days
    return days_old < expired_days

def file_hash(self) -> Optional[str]:
    """
    Return the first defined file hash.

    Returns
    -------
    Optional[str]
        Returns first-defined file hash in order of
        SHA256, SHA1, MD5, SHA256AC (authenticode)

    """
    if self.FileHashes:
        alg_order = {
            Algorithm.SHA256: 0,
            Algorithm.SHA1: 1,
            Algorithm.MD5: 2,
            Algorithm.SHA256AC: 3,
        }

        return next(
            iter(
                sorted(
                    self.FileHashes,
                    key=lambda f_hash: alg_order.get(f_hash.Algorithm, 10),
                )
            )
        ).Value

    return self.Sha256 or self.Sha1 or self.Md5 or self.Sha256Ac

