def _normalize_to_utc(time_stamp: dt.datetime):
    # Normalize datetimes to UTC in case we have mixed timezones in datasets
    if time_stamp.tzinfo is None or time_stamp.tzinfo.utcoffset(time_stamp) is None:
        time_stamp = time_stamp.replace(tzinfo=pytz.UTC)
    else:
        time_stamp = time_stamp.astimezone(pytz.utc)
    return time_stamp

def _find_risky_sudo_session(risky_actions: dict, sudo_sessions: dict):
    risky_sessions = {}
    # Determine if risky event occurs during a session time window
    for key, value in risky_actions.items():
        for sess_key, sess_val in sudo_sessions.items():
            if (
                _normalize_to_utc(sess_val["Start"])
                <= _normalize_to_utc(key)
                <= _normalize_to_utc(sess_val["End"])
            ):
                risky_sessions.update({sess_key: value})
    return risky_sessions

def _find_suspicious_sudo_session(suspicious_actions: list, sudo_sessions: dict):
    risky_sessions = {}
    # Determine if suspicious event occurs during a session time window
    for event in suspicious_actions:
        for value in event.values():
            for sess_key, sess_val in sudo_sessions.items():
                if (
                    _normalize_to_utc(sess_val["Start"])
                    <= _normalize_to_utc(value[0]["TimeGenerated"].iloc[1])
                    <= _normalize_to_utc(sess_val["End"])
                ):
                    risky_sessions.update({sess_key: "Suspicious event pattern"})
    return risky_sessions

def add_observation(self, observation: Observation = None, **kwargs):
    """
    Add an observation.

    Add an observation as an Observation instance or as a
    set of keyword parameters (see Observation class for
    acceptable values). Any keyword parameters that are not
    properties of Observation will be stored in the
    Observation.additional_properties dictionary

    Parameters
    ----------
    observation : Observation
        An observation instance.

    Other Parameters
    ----------------
    kwargs : str, Any
        List of key value pairs of the property names
        and values of the Observation to be stored.

    """
    if observation is not None:
        self.observation_list[observation.caption] = observation
    else:
        req_fields = set(Observation.required_fields())
        missing_fields = req_fields.difference(kwargs.keys())
        if missing_fields:
            raise ValueError(
                "The following fields are required",
                f"in an Observation: {missing_fields}",
            )

        core_fields = {
            key: value
            for key, value in kwargs.items()
            if key in Observation.all_fields()
        }
        new_observation = Observation(**core_fields)
        addl_fields = {
            key: value
            for key, value in kwargs.items()
            if key not in Observation.all_fields()
        }
        # pylint: disable=no-member
        new_observation.additional_properties.update(addl_fields)
        self.observation_list[new_observation.caption] = new_observation

