def get_token(self):
    """Get an authneticaiton token."""
    chosen_account = self.app.get_accounts(username=self.username)
    if chosen_account:
        self.result = self.app.acquire_token_silent_with_error(
            scopes=self.scopes, account=chosen_account[0]
        )
        if not self.result:
            self.result = self._app_auth(self.auth_type)
    else:
        self.result = self._app_auth(self.auth_type)
    self.refresh_token()

def refresh_token(self):
    """Refresh the authentication token."""
    self.result = None
    chosen_account = self.app.get_accounts(username=self.username)
    if chosen_account:
        self.result = self.app.acquire_token_silent_with_error(
            scopes=self.scopes, account=chosen_account[0], force_refresh=True
        )
    if not self.result:
        self.get_token()

def _app_auth(self, auth_type):  # pylint: disable=inconsistent-return-statements
    """Conduct authentication against the application."""
    if auth_type == "interactive":
        return self.app.acquire_token_interactive(scopes=self.scopes)
    if auth_type == "device":
        flow = self.app.initiate_device_flow(scopes=self.scopes)
        if "user_code" not in flow:
            raise ValueError(
                f"Fail to create device flow. Err: {json.dumps(flow, indent=4)}"
            )
        print(flow["message"])
        return self.app.acquire_token_by_device_flow(flow)

def _create_cache(self):
    """Build a suitable token persistence instance based your current OS."""
    if platform.startswith("win"):
        return FilePersistenceWithDataProtection(self.location)
    if platform.startswith("darwin"):
        return KeychainPersistence(self.location, "msal_token", "msal_token_value")
    if platform.startswith("linux"):
        try:
            return LibsecretPersistence(
                self.location,
                schema_name="msal_token",
                attributes={
                    "msal_token1": "msal_token_values",
                    "msal_token2": "msal_token_values",
                },
            )
        except (PersistenceNotFound, ImportError, ValueError):
            print("Unable to create encrypted token cache - using in memory cache.")
            return None

    return FilePersistence(self.location)

def _filter_credential_warning(record) -> bool:
    """Rewrite out credential not found message."""
    if (
        not record.name.startswith("azure.identity")
        or record.levelno != logging.WARNING
    ):
        return True
    message = record.getMessage()
    if ".get_token" in message:
        if message.startswith("EnvironmentCredential"):
            print("Unable to sign-in with environment variable credentials.")
        if message.startswith("AzureCliCredential"):
            print("Unable to sign-in with Azure CLI credentials.")
        if message.startswith("ManagedIdentityCredential"):
            print("Unable to sign-in with Managed Instance credentials.")
    return not message

def _filter_all_warnings(record) -> bool:
    """Filter out credential error messages."""
    if record.name.startswith("azure.identity") and record.levelno == logging.WARNING:
        message = record.getMessage()
        if ".get_token" in message:
            return not message
    return True

def _make_sync(future):
    """Wait for an async call, making it sync."""
    try:
        event_loop = asyncio.get_event_loop()
    except RuntimeError:
        # Generate an event loop if there isn't any.
        event_loop = asyncio.new_event_loop()
        asyncio.set_event_loop(event_loop)
    return event_loop.run_until_complete(future)

def _preprocess_url(url: str, **kwargs) -> SanitizedObservable:
    """
    Check that URL can be parsed.

    Parameters
    ----------
    url : str
        The URL to check
    require_url_encoding : bool
        Set to True if url's require encoding before passing to provider

    Returns
    -------
    SanitizedObservable
        Pre-processed result

    """
    require_url_encoding: bool = kwargs.pop("require_url_encoding", False)
    url = refang_ioc(ioc=url, ioc_type="url")
    clean_url, scheme, host = get_schema_and_host(url, require_url_encoding)

    if scheme is None or host is None:
        return SanitizedObservable(None, f"Could not obtain scheme or host from {url}")
    # get rid of some obvious false positives (localhost, local hostnames)
    with contextlib.suppress(ValueError):
        addr = ip_address(host)
        if addr.is_private:
            return SanitizedObservable(None, "Host part of URL is a private IP address")
        if addr.is_loopback:
            return SanitizedObservable(
                None, "Host part of URL is a loopback IP address"
            )
    if "." not in host:
        return SanitizedObservable(None, "Host is unqualified domain name")

    if scheme.lower() in ["file"]:
        return SanitizedObservable(None, f"{scheme} URL scheme is not supported")

    return SanitizedObservable(clean_url, "ok")

def _preprocess_hash(hash_str: str, **kwargs) -> SanitizedObservable:
    """Ensure Hash has minimum entropy (rather than a string of 'x')."""
    del kwargs
    str_entropy = _entropy(hash_str)
    if str_entropy < 3.0:
        return SanitizedObservable(None, "String has too low an entropy to be a hash")
    return SanitizedObservable(hash_str, "ok")

def _entropy(input_str: str) -> float:
    """Compute entropy of input string."""
    str_len = float(len(input_str))
    return -sum(
        map(
            lambda a: (a / str_len) * math.log2(a / str_len),
            Counter(input_str).values(),
        )
    )

