def _asn_whois_query(query, server, port=43, retry_count=5) -> str:
    """Connect to whois server and send query."""
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as conn:
        conn.connect((server, port))
        conn.send(query.encode())
        response = []
        response_data = None
        while retry_count > 0 and not response_data:
            try:
                response_data = conn.recv(4096).decode()
                if "error" in response_data:
                    raise MsticpyConnectionError(
                        "An error occurred during lookup, please try again."
                    )
                if "rate limit exceeded" in response_data:
                    raise MsticpyConnectionError(
                        "Rate limit exceeded please wait and try again."
                    )
                response.append(response_data)
            except (UnicodeDecodeError, ConnectionResetError):
                retry_count -= 1
                response_data = None
    return "".join(response)

def _cymru_query(query):
    """Query Cymru for ASN information."""
    return _asn_whois_query(query, "whois.cymru.com")

def _radb_query(query):
    """Query RADB for ASN information."""
    return _asn_whois_query(query, "whois.radb.net")

def _parse_asn_response(response) -> dict:
    """Parse ASN response into a dictionary."""
    response_output = {}
    for item in response.split("\n"):
        try:
            key = item.split(":")[0].strip()
            if key and key not in response_output:
                try:
                    response_output[key] = item.split(":")[1].strip()
                except IndexError:
                    continue
            elif key in response_output:
                if not isinstance(response_output[key], list):
                    response_output[key] = [response_output[key]]
                response_output[key].append(item.split(":")[1].strip())
        except IndexError:
            continue
    return response_output

def _parse_asn_ranges(response):
    """Parse ASN ranges response into a list."""
    return [
        item.split(":   ")[1].strip()
        for item in response.split("\n")
        if item.split(":   ")[0].strip() == "route"
    ]

def _rdap_lookup(url: str, retry_count: int = 5) -> httpx.Response:
    """Perform RDAP lookup with retries."""
    rdap_data = None
    while retry_count > 0 and not rdap_data:
        try:
            rdap_data = httpx.get(url)
        except (httpx.WriteError, httpx.ReadError):
            retry_count -= 1
    if not rdap_data:
        raise MsticpyException(
            "Rate limit exceeded - try adjusting query_rate parameter to slow down requests"
        )
    return rdap_data

def _create_net(data: Dict) -> Dict:
    """Create a network object from RDAP data."""
    net_data = data.get("cidr0_cidrs", [None])[0] or {}
    net_prefixes = net_data.keys() & {"v4prefix", "v6prefix"}

    if not net_data or not net_prefixes:
        net_cidr = "No network data retrieved."
    else:
        net_cidr = " ".join(
            f"{net_data[net_prefix]}/{net_data.get('length', '')}"
            for net_prefix in net_prefixes
        )
    address = ""
    created = updated = None
    for item in data["events"]:
        created = item["eventDate"] if item["eventAction"] == "last changed" else None
        updated = item["eventDate"] if item["eventAction"] == "registration" else None
    for entity in data["entities"]:
        address = _find_address(entity)  # type: ignore
    regex = r"[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9-]+(?:\.[a-zA-Z0-9-]+)*"
    emails = re.findall(regex, str(data))
    return {
        "cidr": net_cidr,
        "handle": data["handle"],
        "name": data["name"],
        "startAddress": data["startAddress"],
        "endAddress": data["endAddress"],
        "created": created,
        "updated": updated,
        "address": address,
        "emails": emails,
    }

def _parse_multi_results(self, response: Dict) -> Iterable[Dict]:
    """Parse details of batch response."""
    if not isinstance(response["RawResult"], dict):
        response.update(
            {
                "Result": False,
                "Severity": ResultSeverity.information.value,
                "Details": "Not found",
            }
        )
        yield response

    elif "response" in response["RawResult"]:
        dom_records = response["RawResult"]["response"]
        for dom_record in dom_records:
            result, sev, details = self._parse_one_record(dom_record)
            domain_name = dom_record["domain"]
            yield {
                "Ioc": domain_name,
                "IocType": "dns",
                "Provider": self._provider_name,
                "Result": result,
                "Severity": sev.name,
                "Details": details,
                "RawResult": dom_record,
                "Reference": f"{response['Reference']}?domains[0]={domain_name}",
            }

def _parse_one_record(dom_record: dict):
    record_status = dom_record.get("status_code", 404)
    severity = ResultSeverity.information
    if record_status == 200:
        return (
            True,
            severity,
            {
                "rank": dom_record.get("rank", "0"),
                "page_rank": dom_record.get("page_rank_decimal", 0),
                "error": dom_record.get("error", ""),
            },
        )
    if record_status == 404:
        return (
            True,
            ResultSeverity.warning,
            {
                "rank": dom_record.get("rank", "0"),
                "error": dom_record.get("error", ""),
            },
        )
    return False, ResultSeverity.information, {}

def parse_results(self, response: Dict) -> LookupResult:
    """
    Return the details of the response.

    Parameters
    ----------
    response : Dict
        The returned data response

    Returns
    -------
    Tuple[bool, ResultSeverity, Any]
        bool = positive or negative hit
        ResultSeverity = enumeration of severity
        Object with match details

    """
    if self._failed_response(response) or not isinstance(
        response["RawResult"], dict
    ):
        return LookupResult(
            False, ResultSeverity.information, {"status": "Not found."}
        )
    severity = self._RISK_MAP[response.get("risk", "none")]

    details = {
        "indicator_id": response.get("iid"),
        "threats": response.get("threats", []),
        "last_seen": response.get("stamp_seen", ""),
        "risk_factors": response.get("riskfactors", {}),
        "comments": response.get("comments", {}),
    }

    return LookupResult(True, severity, details)

def _lookup_batch(self, ioc_list: list) -> Iterable[Dict]:
    # build the query string manually - of the form domains[N]=domN&domains[N+1]...
    qry_elements = [
        f"domains[{idx}]={dom}" for idx, dom in zip(range(len(ioc_list)), ioc_list)
    ]

    qry_str = "&".join(qry_elements)
    path = self._QUERIES["dns"].path
    req_url = f"{self._BASE_URL}{path}?{qry_str}"

    try:
        _, req_params = self._substitute_parms("dummy", "dns", None)
        response = self._httpx_client.get(
            url=req_url, headers=req_params["headers"]
        )
        if response.status_code == 200:
            result = {
                "Ioc": ",".join(ioc_list),
                "IocType": "dns",
                "Status": LookupStatus.OK.value,
                "Reference": f"{self._BASE_URL}{path}",
                "RawResult": response.json(),
            }

            yield from self._parse_multi_results(result)
        else:
            yield {
                "Ioc": ",".join(ioc_list),
                "IocType": "dns",
                "Status": response.status_code,
                "Reference": req_url,
                "RawResult": str(response),
                "Result": False,
                "Details": "No response from provider.",
            }
    except (
        LookupError,
        JSONDecodeError,
        NotImplementedError,
        ConnectionError,
    ) as err:
        result_dict = {
            "Ioc": ",".join(ioc_list),
            "IocType": "dns",
            "Details": "\n".join(err.args),
        }
        if isinstance(err, LookupError):
            result_dict["Reference"] = req_url
        yield result_dict  # type: ignore

def parse_results(self, response: Dict) -> Tuple[bool, ResultSeverity, Any]:
    """
    Return the details of the response.

    Parameters
    ----------
    response : Dict
        The returned data response

    Returns
    -------
    Tuple[bool, ResultSeverity, Any]
        bool = positive or negative hit
        ResultSeverity = enumeration of severity
        Object with match details

    """
    if self._failed_response(response) or not isinstance(
        response["RawResult"], dict
    ):
        return False, ResultSeverity.information, "Not found."
    if "pulse_info" in response["RawResult"]:
        pulses = response["RawResult"]["pulse_info"].get("pulses", {})
        pulse_count = len(pulses)
        if pulse_count == 0:
            severity = ResultSeverity.information
            return (
                True,
                severity,
                {
                    "pulse_count": pulse_count,
                    "sections_available": response["RawResult"]["sections"],
                },
            )
        severity = (
            ResultSeverity.warning if pulse_count == 1 else ResultSeverity.high
        )
        return (
            True,
            severity,
            {
                "pulse_count": pulse_count,
                "names": [p.get("name") for p in pulses],
                "tags": [p.get("tags") for p in pulses],
                "references": [p.get("references") for p in pulses],
            },
        )
    return True, ResultSeverity.information, {}

