def parse_results(self, response: Dict) -> Tuple[bool, ResultSeverity, Any]:
    """
    Return the details of the response.

    Parameters
    ----------
    response : Dict
        The returned data response

    Returns
    -------
    Tuple[bool, ResultSeverity, Any]
        bool = positive or negative hit
        ResultSeverity = enumeration of severity
        Object with match details

    """
    severity = ResultSeverity.information
    if self._failed_response(response) or not isinstance(
        response["RawResult"], dict
    ):
        return False, severity, "Not found."
    result = True
    result_dict = {}
    if (
        response["IocType"] in ["ipv4", "ipv6", "url", "dns"]
        and not response["QuerySubtype"]
    ):
        score = response["RawResult"].get("score", 0)
        result_dict.update(
            {
                "score": response["RawResult"].get("score", 0),
                "cats": response["RawResult"].get("cats"),
                "categoryDescriptions": response["RawResult"].get(
                    "categoryDescriptions"
                ),
                "reason": response["RawResult"].get("reason"),
                "reasonDescription": response["RawResult"].get(
                    "reasonDescription", 0
                ),
                "tags": response["RawResult"].get("tags", 0),
            }
        )
        severity = (
            ResultSeverity.information
            if score < 2
            else ResultSeverity.warning
            if 2 <= score < 5
            else ResultSeverity.high
        )
    if (
        response["IocType"] in ["file_hash", "md5_hash", "sha1_hash", "sha256_hash"]
        or response["QuerySubtype"] == "malware"
    ):
        malware = response["RawResult"].get("malware")
        if malware:
            result_dict.update(
                {
                    "risk": malware.get("risk"),
                    "family": malware.get("family"),
                    "reasonDescription": response["RawResult"].get(
                        "reasonDescription", 0
                    ),
                }
            )
            severity = ResultSeverity.high
    if response["IocType"] in ["dns", "ipv4", "ipv6", "hostname"] and response[
        "QuerySubtype"
    ] in ["info", "passivedns", "whois"]:
        records = response["RawResult"].get("total_rows", 0)
        contact = response["RawResult"].get("contact", 0)
        if records:
            result_dict["records"] = records
        elif contact:
            result_dict["contact"] = contact
    return result, severity, result_dict

def parse_results(self, response: Dict) -> Tuple[bool, ResultSeverity, Any]:
    """Return the details of the response."""
    if self._failed_response(response) or not isinstance(
        response["RawResult"], dict
    ):
        return False, ResultSeverity.information, "Not found."

    data = response["RawResult"]["data"]
    result_dict = {
        "countryCode": data.get("countryCode", None),
        "usage": data.get("usageType", None),
        "isp": data.get("isp", None),
        "domain": data.get("domain", None),
        "hostNames": data.get("hostnames", None),
        "lastReportedAt": data.get("lastReportedAt", None),
    }

    score = data.get("abuseConfidenceScore", None)

    if score == 0:
        result_severity = ResultSeverity.information
    elif score <= 50:
        result_severity = ResultSeverity.warning
    elif score > 50:
        result_severity = ResultSeverity.high

    return (True, result_severity, result_dict)

def _err_to_results(result: Dict, err: Exception):
    result["Details"] = err.args
    result["RawResult"] = (
        type(err).__name__ + "\n" + str(err) + "\n" + traceback.format_exc()
    )

def _response_message(status_code):
    if status_code == 404:
        return "Not found."
    if status_code == 401:
        return "Authorization failed. Check account and key details."
    if status_code == 403:
        return "Request forbidden. Allowed query rate may have been exceeded."
    return httpx.codes.get_reason_phrase(status_code) or "Unknown HTTP status code."

def import_provider(cls, provider: str) -> Provider:
    """Import provider class."""
    mod_name, cls_name = cls.PROVIDERS.get(provider, (None, None))

    if not (mod_name and cls_name):
        if hasattr(cls, "CUSTOM_PROVIDERS") and provider in cls.CUSTOM_PROVIDERS:
            return cast(Provider, cls.CUSTOM_PROVIDERS[provider])
        raise LookupError(
            f"No provider named '{provider}'.",
            "Possible values are:",
            ", ".join(list(cls.PROVIDERS) + list(cls.CUSTOM_PROVIDERS)),
        )

    imp_module = importlib.import_module(
        f"msticpy.context.{cls.PACKAGE}.{mod_name}", package="msticpy"
    )
    return getattr(imp_module, cls_name)

