    ts_changed = self._set_pivot_timespan(**kwargs)
    ptanalyzer.set_context("msticpy", "pivot", VERSION, prop)
    obj = ptanalyzer.get_object(host)
    if ts_changed and prop not in ["reputation", "summary", "whois"]:
        obj.reset(prop)
