def qualified_name(self) -> str:
    """Windows qualified account name."""
    if "Name" not in self:
        return ""
    name = self["Name"]
    if "NTDomain" in self and self.NTDomain:
        return f"{self.NTDomain}\\{name}"
    if "UPNSuffix" in self and self.UPNSuffix:
        return f"{name}@{self.UPNSuffix}"
    if "Host" in self and self.Host:
        return f"{self.Host.HostName}\\{name}"
    return name

def _add_related_alert_edges(related_alerts_graph, alert_row, default_node):
    related_alert = SecurityAlert(alert_row)
    if related_alert.primary_account is not None:
        acct_node = _find_graph_node(
            related_alerts_graph,
            "account",
            related_alert.primary_account.qualified_name,
        )
        if acct_node is not None:
            _add_related_alert_edge(related_alerts_graph, acct_node, related_alert)

    if related_alert.primary_process is not None:
        proc_node = _find_graph_node(
            related_alerts_graph,
            "process",
            related_alert.primary_process.ProcessFilePath,
        )
        if proc_node is not None:
            _add_related_alert_edge(related_alerts_graph, proc_node, related_alert)

    if related_alert.primary_host is not None:
        host_node = _find_graph_node(
            related_alerts_graph, "host", related_alert.primary_host["HostName"]
        )
        if host_node is not None:
            _add_related_alert_edge(related_alerts_graph, host_node, related_alert)

    # if we haven't added an edge to this entity from anything else,
    # add one to the alert
    if not related_alerts_graph[related_alert["AlertType"] + "(R)"]:
        _add_related_alert_edge(related_alerts_graph, default_node, related_alert)

def computer(self) -> Optional[str]:
    """Return computer from source event."""
    return self._computer if self._computer is not None else self.fqdn

def fqdn(self) -> Optional[str]:
    """Construct FQDN from host + dns."""
    if self.DnsDomain:
        return f"{self.HostName}.{self.DnsDomain}"
    return self.HostName

def host_name(self) -> Optional[str]:
    """Return host name column."""
    return self.host_name_column

def hostname(self) -> str:
    """Return the Hostname (not FQDN) of the host associated with the alert."""
    return self.primary_host.HostName if self.primary_host is not None else None

def _extract_src_entity(self, src_entity: Mapping[str, Any]):
    """
    Extract source entity properties.

    Parameters
    ----------
    src_entity : Mapping[str, Any]
        The source mappable object from which to
        extract entity properties.

    """
    schema_dict = self._entity_schema.copy()
    schema_dict["Type"] = None
    for attr, val in schema_dict.items():
        if attr not in src_entity:
            continue
        self[attr] = src_entity[attr]

        if val is None:
            continue
        try:
            # If the property is an enum
            if val in ENTITY_ENUMS.values():
                self[attr] = val[src_entity[attr]]
            elif val in ENTITY_ENUMS:
                self[attr] = ENTITY_ENUMS[val][src_entity[attr]]
                continue
        except KeyError:
            # Catch key errors from invalid enum values
            self[attr] = None

        if isinstance(val, tuple):
            self._instantiate_from_value(attr, val, src_entity)
        else:
            self._instantiate_from_entity(attr, val, src_entity)

def _instantiate_from_value(self, attr, val, src_entity):
    # if the property is a collection
    entity_type = None
    if isinstance(val[1], (type)) and issubclass(val[1], Entity):
        entity_type = val[1]
    entity_list = [
        Entity.instantiate_entity(col_entity, entity_type=entity_type)
        for col_entity in src_entity[attr]
    ]

    self[attr] = entity_list
    for child_entity in entity_list:
        if isinstance(child_entity, Entity):
            self.add_edge(child_entity, edge_attrs={"name": attr})

def _instantiate_from_entity(self, attr, val, src_entity):
    # else try to instantiate an entity
    entity_type = None
    if isinstance(val, type) and issubclass(val, Entity):
        entity_type = val
    self[attr] = Entity.instantiate_entity(
        src_entity[attr], entity_type=entity_type
    )
    if isinstance(self[attr], Entity):
        self.add_edge(self[attr], edge_attrs={"name": attr})

def _resolve_entity_refs(self):
    """
    Resolve and replace entity properties that are '$ref' type.

    When serialized the nested entities can be references to other
    referenced objects in the collection. This iterates through
    the raw entities and replaces referenced items with the actual
    object reference. If the Id referenced by this property exists
    in the entities dictionary we replace the original property
    with a reference to the entity in the dictionary.

    """
    for _, entity in self._src_entities.items():
        if not isinstance(entity, Entity):
            continue
        # Resolve all the simple references
        ref_props = {
            name: prop
            for name, prop in entity.properties.items()
            if isinstance(prop, dict) and "$ref" in prop
        }
        for prop_name, prop_val in ref_props.items():
            entity_id = prop_val["$ref"]
            if entity_id in self._src_entities:
                entity[prop_name] = self._src_entities[entity_id]
                entity.add_edge(entity[prop_name], edge_attrs={"name": prop_name})
        # Resolve all the lists of references
        ref_props_multi = {
            name: prop
            for name, prop in entity.properties.items()
            if isinstance(prop, list)
            and any(elem for elem in prop if "$ref" in elem)
        }
        for prop_name, prop_val in ref_props_multi.items():
            for idx, elem in enumerate(prop_val):
                if not isinstance(elem, dict):
                    continue
                entity_id = elem["$ref"]
                if entity_id in self._src_entities:
                    entity[prop_name][idx] = self._src_entities[entity_id]
                    entity.add_edge(
                        self._src_entities[entity_id],
                        edge_attrs={"name": prop_name},
                    )

def _extract_entities(self, src_row):  # noqa: MC0001
    input_entities = []

    if isinstance(src_row.ExtendedProperties, str):
        try:
            ext_props = json.loads(src_row["ExtendedProperties"])
            for ent, val in ext_props.items():
                if ent in ["IpAddress", "Username"]:
                    input_entities.append({"Entity": val, "Type": ent})
        except json.JSONDecodeError:
            pass

    if isinstance(src_row.Entities, str):
        try:
            input_entities += json.loads(src_row["Entities"])
        except json.JSONDecodeError:
            pass
    elif isinstance(src_row.Entities, list):
        input_entities += src_row.Entities

    for ent in input_entities:
        try:
            entity = Entity.instantiate_entity(ent)
        except TypeError:
            # if we didn't instantiate a known entity
            # just add it as it is
            entity = UnknownEntity(**ent)
        if "$id" in ent:
            self._src_entities[ent["$id"]] = entity
        self._extract_child_entities(ent)
    self._resolve_entity_refs()

def _extract_child_entities(self, src_entity):
    for prop in src_entity.values():
        if prop is None:
            continue
        if (
            isinstance(prop, dict)
            and "$id" in prop
            and prop["$id"] not in self._src_entities
        ):
            self._extract_child_entities(prop)
            try:
                entity = Entity.instantiate_entity(prop)
            except TypeError:
                # if we didn't instantiate a known entity
                # just add it as it is
                entity = UnknownEntity(**prop)
            self._src_entities[prop["$id"]] = entity

def __iter__(self):
    """Iterate over entity_properties."""
    return iter(self.properties)

def __len__(self) -> int:
    """Return length/number of entity_properties."""
    return len(self.properties)

def __repr__(self) -> str:
    """Return repr of entity."""
    params = ", ".join(
        f"{name}={val}" for name, val in self.properties.items() if val
    )
    if self.edges:
        params = f"{params}, edges={'. '.join(str(edge) for edge in self.edges)}"

    if len(params) > 80:
        params = f"{params[:80]}..."
    return f"{self.__class__.__name__}({params})"

def __hash__(self) -> int:
    """Return the hash of the entity based on non-empty property values."""
    return hash(
        " ".join(
            f"{prop}:{val}" for prop, val in self.properties.items() if str(val)
        )
    )

def properties(self) -> dict:
    """
    Return dictionary properties of entity.

    Returns
    -------
    dict
        Entity properties.

    """
    return {
        name: value
        for name, value in self.__dict__.items()
        if not name.startswith("_") and name != "edges" and value
    }

def path_separator(self):
    """Return the path separator used by the file."""
    if (
        self.Directory and "/" in self.Directory
    ) or self.OSFamily != OSFamily.Windows:
        return "/"
    return "\\"

def _create_from_event(self, src_event, role):
    if role == "new" and "NewProcessName" in src_event:
        self._add_paths(src_event["NewProcessName"])
    elif role == "parent" and "ParentProcessName" in src_event:
        self._add_paths(src_event["ParentProcessName"])
    elif "Directory" in src_event and "FileName" in src_event:
        self._add_paths(src_event["Directory"], file_name=src_event["FileName"])

def _add_paths(self, full_path, file_name=None):
    if "/" in full_path:
        self.PathSeparator = "/"
        self.OSFamily = OSFamily.Linux
    else:
        self.PathSeparator = "\\"
        self.OSFamily = OSFamily.Windows

    if file_name:
        self.Name = file_name
        self.Directory = full_path
        self.FullPath = self.Directory + self.PathSeparator + self.Name
    else:
        self.FullPath = full_path
        self.Name = full_path.split(self.PathSeparator)[-1]
        self.Directory = full_path.split(self.PathSeparator)[:-1]

def _extract_entities(ents: list):
    """Extract all entities from a set and replace $ref elements."""
    base_ents = _generate_base_ents(ents)
    out_ents = []
    for entity in ents:
        if isinstance(entity, dict) and "$ref" in entity:
            out_ents.append(_find_original_entity(entity, base_ents))
        else:
            for k, val in entity.items():
                if isinstance(val, (list, dict)):
                    if isinstance(val, list):
                        nested_ents = []
                        for item in val:
                            if isinstance(item, dict) and "$ref" in item:
                                nested_ents.append(
                                    _find_original_entity(item, base_ents)
                                )
                                entity[k] = nested_ents
                    elif isinstance(val, dict) and "$ref" in val:
                        entity[k] = _find_original_entity(val, base_ents)
            out_ents.append(entity)
    return out_ents

def _find_original_entity(ent, base_ents):
    """Find the original entity referenced by $ref entity."""
    try:
        id = ent["$ref"]
        return next(bent for bent in base_ents if ("$id" in bent) and bent["$id"] == id)
    except StopIteration:
        return ent

def _generate_base_ents(ents: list) -> list:  # noqa: MC0001
    """Generate a list of all enties form a set of nested entities."""
    base_ents = []
    for ent in ents:
        base_ents.append(ent)
        for _, item in ent.items():
            if isinstance(item, list):
                for prop in item:
                    if isinstance(prop, dict) and "$id" in prop.keys():
                        base_ents.append(prop)
                        for val in prop:
                            if isinstance(prop[val], list):
                                for p in prop[val]:
                                    if isinstance(p, dict) and "$id" in p.keys():
                                        base_ents.append(p)
                            elif (
                                isinstance(prop[val], dict)
                                and "$id" in prop[val].keys()
                            ):
                                base_ents.append(val)
            elif isinstance(item, dict) and "$id" in item.keys():
                base_ents.append(item)
    return base_ents

def print_debug(*args):
    """Print args to std_out (Debug version)."""
    if not _DEBUG:
        return
    print(*args)

def get_value(self, path: str) -> Any:
    """Return setting value at `path`."""
    return self._get_elem_from_path(path, self.mp_config)

def get_control(self, path: str) -> Any:
    """Return the control stored at `path`."""
    return self._get_elem_from_path(path, self.controls)

def _set_ctrl_values(self, path: str):
    """Recursively set settings from control values."""
    ctrl_tree = self.get_control(path)
    if isinstance(ctrl_tree, widgets.Widget):
        print_debug("_set_ctrl_values - widget", ctrl_tree)
        curr_value = py_to_widget(self.get_value(path), ctrl=ctrl_tree)
        if curr_value:
            ctrl_tree.value = curr_value
    elif isinstance(ctrl_tree, SettingsControl):
        print_debug(
            "_set_ctrl_values - _SettingsControl",
            ctrl_tree,
            ctrl_tree.value,
            path,
            self.get_value(path),
        )
        curr_value = self.get_value(path)
        if curr_value:
            ctrl_tree.value = curr_value
    elif isinstance(ctrl_tree, dict):
        for key in ctrl_tree:
            self._set_ctrl_values(f"{path}.{key}")

def _get_ctrl_values(self, path: str):
    """Recursively save values in the control at `path` to settings."""
    ctrl_tree = self.get_control(path)
    print_debug(
        type(ctrl_tree),
        "instance check",
        isinstance(ctrl_tree, (widgets.Widget, SettingsControl)),
    )
    if isinstance(ctrl_tree, (widgets.Widget, SettingsControl)):
        return widget_to_py(ctrl_tree)
    if isinstance(ctrl_tree, dict):
        return {key: self._get_ctrl_values(f"{path}.{key}") for key in ctrl_tree}
    raise ValueError(f"No control found at path {path}")

def _get_settings_ctrls(self, prov_name, conf_path):
    if not prov_name:
        return widgets.VBox([], layout=self.no_border_layout("95%"))

    setting_path = f"{conf_path}.{prov_name}"
    prov_ctrl = self.mp_controls.get_control(setting_path)
    if not isinstance(prov_ctrl, UserDefQryProvCtrl):
        prov_ctrl = UserDefQryProvCtrl(prov_name)
        self.mp_controls.set_control(setting_path, prov_ctrl)

    curr_val = self.mp_controls.get_value(setting_path)
    if curr_val is None:
        curr_val = self._get_default_values(prov_name, conf_path)
    else:
        if "." in prov_name:
            prov, child = prov_name.split(".", maxsplit=1)
            curr_val = {prov: {child: curr_val}}
        else:
            curr_val = {prov_name: curr_val}

    prov_ctrl.value = curr_val

    return prov_ctrl

def _get_settings_ctrls(self, prov_name, conf_path):
    if not prov_name:
        return widgets.VBox([], layout=self.no_border_layout("95%"))

    setting_path = f"{conf_path}.{prov_name}"
    prov_ctrl = self.mp_controls.get_control(setting_path)
    if not isinstance(prov_ctrl, UserDefLoadComponent):
        prov_ctrl = UserDefLoadComponent(
            self.mp_controls, prov_name, self._COMP_PATH
        )
        self.mp_controls.set_control(setting_path, prov_ctrl)

    curr_val = self.mp_controls.get_value(setting_path)
    prov_ctrl.value = curr_val
    return prov_ctrl

def widget_to_py(ctrl: Union[widgets.Widget, SettingsControl]) -> Any:
    """
    Adjust type and format of value returned from `ctrl.value`.

    Parameters
    ----------
    ctrl : Union[widgets.Widget, SettingsControl]
        The source widget

    Returns
    -------
    Any
        Converted value.

    Notes
    -----
    This function handles conversion of widget values to
    configuration (Python) values.

    """
    if isinstance(ctrl, widgets.Checkbox):
        return ctrl.value
    if isinstance(ctrl, widgets.Textarea) and getattr(ctrl, "tag", None) == "txt_dict":
        return txt_to_dict(ctrl.value) or None
    if isinstance(ctrl, widgets.Textarea) and getattr(ctrl, "tag", None) == "list":
        return ctrl.value.split("\n") if ctrl.value else []
    if isinstance(ctrl, _TEXT_WIDGETS):
        if ctrl.value == "":
            return None
        return str(ctrl.value)
    if isinstance(ctrl, widgets.SelectMultiple):
        return list(ctrl.value)
    return None if not ctrl.value else ctrl.value

def txt_to_dict(txt_val: str) -> Dict[str, Any]:
    """
    Return dict from string of "key:val; key2:val2" pairs.

    Parameters
    ----------
    txt_val : str
        The key/value string (items separated by ";",
        key/value separated by ":")

    Returns
    -------
    Dict[str, Any]
        Dictionary of key/values

    """
    if not txt_val:
        return {}
    kvpairs = [
        kv_pair.strip().split(":", maxsplit=1)
        for kv_pair in txt_val.split("\n")
        if kv_pair.strip()
    ]
    return {
        kval[0].strip(): kval[1].strip() if len(kval) > 1 else None for kval in kvpairs
    }

def value(self) -> Union[str, Dict[str, Optional[str]]]:
    """
    Return the value of the control.

    Returns
    -------
    Union[str, Dict[str, Optional[str]]]
        Either a string value or a dict of:
        {"EnvironmentVar": value} or
        {"KeyVault": value or None}

    """
    if self.rb_store_type.value == STORE_TEXT:
        return widget_to_py(self.txt_val)
    return {self.rb_store_type.value: widget_to_py(self.txt_val)}

def get_defn(self, path: str) -> Union[Dict[str, Any], Tuple[str, Any]]:
    """Return the setting definition at `path`."""
    defn = self._get_elem_from_path(path, self.config_defn)
    if defn is not None:
        return defn
    if path.startswith("AzureSentinel.Workspaces"):
        path = re.sub(
            r"(?P<root>AzureSentinel\.Workspaces\.)([^.]+)", r"\1Default", path
        )
    return self._get_elem_from_path(path, self.config_defn)

def _get_default_values(self, prov_name, conf_path):
    defn_path = f"{conf_path}.{prov_name}"
    prov_defn = self.mp_controls.get_defn(defn_path)
    def_settings = {}
    if prov_defn is None:
        return {"alias": None}
    for setting, defn in prov_defn.items():
        st_type, st_opts = defn if isinstance(defn, tuple) else "str", {}
        if st_type == "str":
            def_settings[setting] = st_opts.get("default")
        elif st_type == "bool":
            def_settings[setting] = st_opts.get("default", False)
    return def_settings

def _get_prov_ctrls(prov_name, mp_controls, conf_path, prov_instance_name: str = None):
    ctrls: List[widgets.Widget] = []
    if not prov_name:
        return widgets.VBox(ctrls, layout=CompEditDisplayMixin.no_border_layout("95%"))
    # prov_path = f"{conf_path}.{prov_name}"
    if prov_instance_name:
        instance_path = f"{conf_path}.{prov_name}-{prov_instance_name}"
    else:
        instance_path = f"{conf_path}.{prov_name}"
    defn_path = f"{conf_path}.{prov_name}"
    prov_defn = mp_controls.get_defn(defn_path)

    for setting in prov_defn:
        if setting != "Args":
            wgt = get_wgt_ctrl(
                setting_path=defn_path,
                var_name=setting,
                mp_controls=mp_controls,
                instance_name=prov_instance_name,
            )
            if setting == "Provider":
                wgt.disabled = True
            ctrls.append(wgt)
            continue

        setting_path = f"{instance_path}.{setting}"
        setting_defn_path = f"{defn_path}.{setting}"
        for var_name in prov_defn.get(setting):
            comp_defn = mp_controls.get_defn(f"{setting_defn_path}.{var_name}")
            if get_defn_or_default(comp_defn)[0] == "cred_key":
                arg_ctrl = get_arg_ctrl(setting_path, var_name, mp_controls)
                ctrls.append(arg_ctrl.hbox)
            else:
                ctrls.append(
                    get_wgt_ctrl(
                        setting_path=setting_defn_path,
                        var_name=var_name,
                        mp_controls=mp_controls,
                        instance_name=prov_instance_name,
                    )
                )

    return widgets.VBox(ctrls)

def _get_settings_path(settings, path):
    path_elems = path.split(".")
    curr_node = settings
    for elem in path_elems:
        curr_node = curr_node.get(elem)
        if curr_node is None:
            break
    return curr_node

def __init__(self, mp_controls: MpConfigControls):
    """Initialize the class. Set the controls and retrieve settings."""
    super().__init__(description=self._DESCRIPTION)

    self.mp_controls = mp_controls
    self.comp_defn = self._get_settings_path(
        mp_controls.config_defn, self._COMP_PATH
    )
    self.settings = self._get_settings_path(mp_controls.mp_config, self._COMP_PATH)

    self.help.set_help(self._HELP_TEXT, self._HELP_URI)

    self.controls = {}

    get_or_create_mpc_section(self.mp_controls, self._COMP_PATH)
    prov_defn = mp_controls.get_defn(self._COMP_PATH)

    w_style = {
        "style": {"description_width": "100px"},
        "layout": widgets.Layout(width="80%"),
    }
    self.controls = {
        setting: get_wgt_ctrl(self._COMP_PATH, setting, mp_controls, w_style)
        for setting in prov_defn
    }
    self.edit_frame.children = list(self.controls.values())
    self.btn_save.on_click(self._save_settings)

def _create_ctrl_dict(self, config_dict):
    """Create a blank control dictionary from settings."""
    ctrl_dict = config_dict.copy()
    for name, val in ctrl_dict.items():
        if (
            isinstance(val, dict)
            and STORE_KEYVAULT not in val
            and STORE_ENV_VAR not in val
        ):
            ctrl_dict[name] = self._create_ctrl_dict(val)
        else:
            ctrl_dict[name] = None
    return ctrl_dict

def _get_elem_from_path(path, member_dict: Dict[str, Any]):
    """Return an item at the path from `member_dict`."""
    paths = path.split(".")
    current_elem = member_dict
    for elem in paths:
        next_elem = current_elem.get(elem)
        if next_elem is None:
            return next_elem
        current_elem = next_elem
    return current_elem

def _del_elem_at_path(self, path: str, member_dict: Dict[str, Any]):
    """Delete an item at `path`."""
    parent_path, tgt_key = path.rsplit(".", maxsplit=1)
    parent = self._get_elem_from_path(parent_path, member_dict)
    if parent is not None and tgt_key in parent:
        del parent[tgt_key]

def set_value(self, path: str, value: Any):
    """Set setting value at path to `value`."""
    self._set_elem_at_path(path, self.mp_config, value)

def del_value(self, path: str, keep_ctrl: bool = False):
    """Delete setting item at `path`."""
    self._del_elem_at_path(path, self.mp_config)
    if not keep_ctrl:
        self.del_control(path)

def del_control(self, path: str):
    """Delete the control stored at `path`."""
    self._del_elem_at_path(path, self.controls)

def rename_path(self, old_path: str, new_path: str):
    """Rename a setting from `old_path` to `new_path`."""
    old_path_elems = old_path.rsplit(".", maxsplit=1)
    new_path_elems = new_path.rsplit(".", maxsplit=1)
    if (
        old_path_elems[0] != new_path_elems[0]
        or len(old_path_elems) == 1
        or len(new_path_elems) == 1
    ):
        raise ValueError(
            "Can only rename the bottom element of paths", old_path, new_path
        )
    path_root = old_path_elems[0]
    src_key = old_path_elems[1]
    tgt_key = new_path_elems[1]
    for setting_dict in (self.mp_config, self.controls):
        parent_elem = self._get_elem_from_path(path_root, setting_dict)
        parent_elem[tgt_key] = parent_elem.get(src_key)
        if src_key in parent_elem:
            del parent_elem[src_key]

def save_ctrl_values(self, path: str):
    """Save the values in the control at `path` to settings."""
    self.set_value(path, self._get_ctrl_values(path))

def _current_path(self) -> str:
    """Return current settings path."""
    return f"{self._COMP_PATH}.{self.select_item.label}"

def _del_provider(self, btn):
    """Delete the currently selected provider."""
    del btn
    if not self.select_item.label:
        return
    self.mp_controls.del_value(self._current_path)
    remaining_opts = self._get_select_opts()
    self.select_item.options = remaining_opts
    if remaining_opts:
        self.select_item.label = remaining_opts[-1][0]

def _save_provider(self, btn):
    """Save/update the currently edited provider settings."""
    del btn
    if not self.select_item.label:
        return
    self.mp_controls.save_ctrl_values(self._current_path)
    val_results = self.mp_controls.validate_setting(self._current_path)
    status = "  ".join(res[1] for res in val_results if not res[0])
    if status:
        self.set_status(status)

def _validate_ws(workspace, mp_controls, conf_path):
    """Validate the settings for a workspace."""
    defn_path = f"{conf_path}.Default"

    if not workspace:
        return False, "Workspace name must be supplied."
    prov_path = f"{conf_path}.{workspace}"
    results = mp_controls.validate_setting(path=prov_path, defn_path=defn_path)
    status = []
    validated = True
    for valid, mssg in results:
        if not valid:
            validated = False
            status.append(mssg)
    return validated, "  ".join(status)

def _yml_extract_type(self, conf_val):
    """Extract type and options from definition."""
    if not conf_val or "(" not in conf_val or ")" not in conf_val:
        return "unknown", {}
    val_type_match = re.match(
        r"(?P<type>[^()]+)\((?P<params>.*)\)$", conf_val.strip()
    )
    val_type = val_type_match.groupdict().get("type")
    val_param_str = val_type_match.groupdict().get("params", "")

    if val_param_str:
        val_params = {
            param.split("=")[0].strip(): param.split("=")[1].strip()
            for param in val_param_str.split(",")
            if "=" in param
        }
        val_params = {
            key: True if val == "True" else False if val == "False" else val
            for key, val in val_params.items()
        }
    else:
        val_params = {}
    if "options" in val_params:
        val_params["options"] = [
            val.strip("'\"")
            for val in val_params["options"].strip()[1:-1].split("; ")
        ]
    if "mp_defn_path" in val_params:
        defn_path = val_params.pop("mp_defn_path").strip(" /\"'").replace("/", ".")
        defn = self._get_elem_from_path(defn_path, self._raw_config_defn)
        val_params["defn"] = defn
    default_val = val_params.get("default", "")
    if isinstance(default_val, str):
        if default_val.strip().startswith("["):
            # This is a default list - so we need to parse it
            val_params["default"] = [
                val.strip("'\"")
                for val in re.split(r"\s*;\s*|\s*,\s*", default_val.strip()[1:-1])
            ]
        else:
            val_params["default"] = default_val.strip("'\"")
    return val_type, val_params

def _convert_mp_config(self, mp_conf_item):
    """Convert definition dictionary to extract definitions."""
    if isinstance(mp_conf_item, list):
        return self._convert_mp_config_list(mp_conf_item)
    if isinstance(mp_conf_item, dict):
        return self._convert_mp_config_dict(mp_conf_item)
    return mp_conf_item

def _convert_mp_config_dict(self, mp_conf_dict):
    """Recursively convert definition dictionary to extract definitions."""
    out_dict = {}
    for key, val in mp_conf_dict.items():
        if isinstance(val, dict):
            out_dict[key] = self._convert_mp_config_dict(val)
        elif isinstance(val, list):
            out_dict[key] = self._convert_mp_config_list(val)
        else:
            key_type, opts = self._yml_extract_type(val)
            out_dict[key] = val if key_type == "unknown" else (key_type, opts)
    return out_dict

def _convert_mp_config_list(self, mp_conf_list):
    """Recursively convert definition list to extract definitions."""
    out_list = []
    for val in mp_conf_list:
        if isinstance(val, dict):
            out_list.append(self._convert_mp_config_dict(val))
        elif isinstance(val, list):
            out_list.append(self._convert_mp_config_list(val))
        else:
            key_type, opts = self._yml_extract_type(val)
            out_list.append(val if key_type == "unknown" else (key_type, opts))
    return out_list

def current_config_file(self):
    """Return the currently loaded configuration file path."""
    return self.mp_conf_file.current_file

def _is_none_and_not_required(value, val_type, val_opts):
    if value is None or (val_type == "str" and not value):
        return not val_opts.get("required", True)
    return False

def _validate_string(value, path, val_type, val_opts):
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    if not isinstance(value, str):
        return ValidationResult(
            False,
            f"Value '{value}' of type {type(value)} should be type {val_type} - {mssg}",
        )
    if "options" in val_opts and value not in val_opts["options"]:
        return ValidationResult(
            False,
            f"Value {value} must be one of {', '.join(val_opts['options'])} - {mssg}",
        )
    if val_opts.get("format") == "uuid" and not is_valid_uuid(value):
        return ValidationResult(
            False,
            f"Value {value} should be a UUID - {mssg}",
        )
    return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")

def _validate_bool(value, path, val_type, val_opts):
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    if not isinstance(value, bool):
        return ValidationResult(
            False,
            f"Value '{value}' of type {type(value)} should be type {val_type} - {mssg}",
        )
    return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")

def _validate_m_enum(value, path, val_type, val_opts):
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    if not isinstance(value, (str, list)):
        return ValidationResult(
            False,
            f"Value '{value}' of type {type(value)} should be type {val_type} - {mssg}",
        )
    if "options" in val_opts:
        if isinstance(value, str) and value not in val_opts["options"]:
            return ValidationResult(
                False,
                f"Value {value} must be one of {', '.join(val_opts['options'])} - {mssg}",
            )
        if not isinstance(value, list):
            return ValidationResult(
                False,
                f"Value '{value}' should be a string or list. "
                + f"Must be one of {', '.join(val_opts['options'])} - {mssg}",
            )
        invalid_opts = [val for val in value if val not in val_opts["options"]]
        if invalid_opts:
            return ValidationResult(
                False,
                f"Invalid values '{invalid_opts}' found. "
                + f"Must be one of {', '.join(val_opts['options'])} - {mssg}",
            )
    return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")

def _validate_txt_dict(value, path, val_type, val_opts):
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    if isinstance(value, dict):
        for d_key, d_val in value.items():
            if not isinstance(d_key, str):
                return ValidationResult(
                    False,
                    f"Key {d_key} of {value} must be a string - {mssg}",
                )
            if not isinstance(d_val, (str, int, bool)):
                return ValidationResult(
                    False,
                    f"Value {d_val} of key {d_key} in {value} must be a"
                    + f" string, int or bool - {mssg}",
                )
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    return ValidationResult(False, f"Value {value} should be a dictionary - {mssg}")

def _validate_list(value, path, val_type, val_opts):
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    if isinstance(value, list):
        for item_val in value:
            expected_type = val_opts.get("elem_type", "str")
            val_type = type(item_val).__name__
            if expected_type != val_type:
                return ValidationResult(
                    False,
                    f"Item {item_val} of {value} expected to be a {expected_type} - {mssg}",
                )
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    return ValidationResult(False, f"Value {value} should be a list - {mssg}")

def _validate_defn(value, path, val_type, val_opts):
    """
    Validate a compound type definition.

    We want to validate a value against a definition like:
    ::
        cred_key:
            one_of:
                - str: str()
                - EnvironmentVar: str()
                - KeyVault: str(required=False)

    This only handles this type of definition and only looks at
    the "required" flag in the options. We'll extend this checker if we
    need to for other options.

    """
    mssg = _get_mssg(value, path)
    if _is_none_and_not_required(value, val_type, val_opts):
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")

    # This only handles "one_of" lists of alternatives
    opt_list = val_opts.get("defn", {}).get("one_of")
    if not opt_list:
        return ValidationResult(True, f"{_VALID_SUCCESS} {mssg}")
    # pull the definitions (val_type and val_opts) for each item into a dict
    opt_dict = {next(iter(val.keys())): next(iter(val.values())) for val in opt_list}

    # if the checked value is a string, validate the string
    if isinstance(value, str) and "str" in opt_dict:
        opt_v_opts = {"required": "required=False" not in opt_dict["str"]}
        return _validate_string(value, path, "str", opt_v_opts)

    # If the value is a dict
    if isinstance(value, dict):
        # We assume that the value is a dict with a single key
        v_key, v_val = next(iter(value.items()))
        # If the name is in the one_of dictionary names
        if v_key in opt_dict:
            # get the element type
            opt_v_type = re.sub(r"\(.*\)", "", opt_dict[v_key])
            # add "required=False" if that is the value options for this item
            opt_v_opts = {"required": "required=False" not in opt_dict[v_key]}
            # get the validator function for the option type and use that
            # to check the actual value
            _validator = _VALIDATORS.get(opt_v_type, _validate_string)
            return _validator(v_val, f"{path}.{v_key}", opt_v_type, opt_v_opts)
    # Otherwise the validation failed
    return ValidationResult(
        False,
        f"Value type {type(value)} does not match definition {val_opts['defn']} - {mssg}",
    )

def border_layout(width="95%"):
    """Return border widget layout."""
    return widgets.Layout(
        **{
            "width": width,
            "border": "solid gray 1px",
            "margin": "1pt",
            "padding": "5pt",
        }
    )

def no_border_layout(width="95%"):
