def __init__(self, description: str = None):
    """Initialize the class. Set a label with `description` as content."""
    self.inner_frame = widgets.HBox(layout=self.border_layout("99%"))
    self.description = widgets.Label(value=description or "")
    # self.description.style = {"visibility": "visible" if description else "hidden"}
    self.help = CompEditHelp()
    # self.status = widgets.Label(layout=widgets.Layout(width="99%"))
    self.layout = widgets.VBox(
        [self.description, self.inner_frame, self.help.layout, self.status]
    )

def _get_default_values(self, prov_name, conf_path):
    wkspace = None
    if "." in prov_name:
        defn_name, wkspace = prov_name.split(".", maxsplit=1)
    else:
        defn_name = "provider"
    defn_path = f"{conf_path}.{defn_name}"
    prov_defn = self.mp_controls.get_defn(defn_path)
    if prov_defn is None:
        self.set_status(f"No definition for this provider was found: {prov_name}")
        return {}
    def_settings = {}
    for setting, defn in prov_defn.items():
        st_type, st_opts = defn if isinstance(defn, tuple) else "str", {}
        if st_type == "bool":
            def_settings[setting] = st_opts.get("default", False)
        elif st_type == "str":
            def_settings[setting] = st_opts.get("default")
    if wkspace:
        return {defn_name: {wkspace: def_settings}}
    return {defn_name: def_settings}

def _update_settings(self, ws_settings):
    """Update current controls with workspace settings."""
    if not ws_settings:
        self.set_status("Could not resolve workspace from URL")
        return
    ws_name = next(iter(ws_settings))
    _get_named_control(self.edit_ctrls, "Name").value = ws_name
    for setting, value in ws_settings[ws_name].items():
        ctrl = _get_named_control(self.edit_ctrls, setting)
        if ctrl is None or ctrl.value:
            # don't overwrite existing settings
            continue
        ctrl.value = value

def _resolve_settings(self, btn):
    """Resolve missing settings for workspace."""
    del btn
    subscription_id = _get_named_control(self.edit_ctrls, "SubscriptionId").value
    workspace_id = _get_named_control(self.edit_ctrls, "WorkspaceId").value
    workspace_name = _get_named_control(self.edit_ctrls, "WorkspaceName").value
    resource_group = _get_named_control(self.edit_ctrls, "ResourceGroup").value
    if not (workspace_id or workspace_name):
        self.set_status(
            "Need at least WorkspaceId or WorkspaceName to lookup settings."
        )
        return
    if workspace_id:
        self._update_settings(
            ms_sentinel().get_workspace_settings(workspace_id=workspace_id)
        )
    else:
        self._update_settings(
            ms_sentinel().get_workspace_settings_by_name(
                workspace_name=workspace_name,
                subscription_id=subscription_id,
                resource_group=resource_group,
            )
        )

def _get_named_control(edit_ctrls, name):
    """Get the control with matching name."""
    try:
        return next(ctrl for ctrl in edit_ctrls.children if ctrl.description == name)
    except StopIteration:
        return None

def clear_status(self):
    """Clear the status text."""
    self.status.value = ""

def __str__(self):
    """Print the alert contents to stdout."""
    alert_props = str(super().__str__())

    if self.extended_properties:
        str_rep = [
            f"ExtProp: {prop}: {val}"
            for prop, val in self.extended_properties.items()
        ]
        alert_props = alert_props + "\n" + "\n".join(str_rep)

    return alert_props

def set_help(self, help_text: str = "", help_uri: Dict[str, str] = None):
    """Set the help string (HTML) and URIs."""
    if not help_uri:
        help_uri = self._DEFAULT_URI
    help_uris = "<br>".join(
        f"<a href='{uri}' target='_blank' style='{self._HELP_STYLE}'>Online: {title}</a>"
        for title, uri in help_uri.items()
    )
    help_text = "<br>".join(
        [
            help_text,
            help_uris,
        ]
    )
    self.html_help.value = help_text

def layout(self):
    """Return the parent widget."""
    return self.accdn_help

def layout(self):
    """Return the widget layout for the control."""
    return widgets.VBox(list(self.controls.values()))

def value(self) -> Union[str, Dict[str, Optional[str]]]:
    """
    Return the current value of the control.

    Returns
    -------
    Union[str, Dict[str, Optional[str]]]
        The value dict.
        In cases where optional 'alias' and 'connect' settings
        are not used this will be an empty dictionary.

    """
    alias = {"alias": self.txt_alias.value} if self.txt_alias.value else {}
    connect = (
        {"connect": self.cb_connect.value} if not self.cb_connect.value else {}
    )
    return {**alias, **connect}

def _get_val_from_ctrl(self, val_dict):
    """Recursive get values from control dictionary."""
    ctrl_val = {}
    if not val_dict:
        return val_dict
    for name, value in val_dict.items():
        if isinstance(value, widgets.Label):
            continue
        if isinstance(value, dict):
            ctrl_val[name] = self._get_val_from_ctrl(value)
        elif isinstance(value, widgets.Widget):
            ctrl_val[name] = widget_to_py(ctrl=value)
        else:
            ctrl_val[name] = value
    return ctrl_val

def __init__(self, tabs: Optional[Dict[str, CETabControlDef]] = None):
    """
    Initialize the CompEditTabs class.

    Parameters
    ----------
    tabs : Optional[Dict[str, Tuple[type, Union[List[Any], Dict[str, Any]]]]], optional
        Tab definitions or contents, by default None.
        Each definition can be a Tuple of class and list of args
        or a Tuple of class and dict of kwargs.

    """
    self.tab = widgets.Tab()
    self.layout = self.tab
    tabs = tabs or {}
    self._tab_state: List[widgets.Widget] = []
    self._tab_lazy_load: Dict[int, CETabControlDef] = {}
    self._tab_names: List[str] = []
    self.controls: Dict[str, Any] = {}
    if tabs:
        for tab_name, tab_ctrl in tabs.items():
            if isinstance(tab_ctrl, CEItemsBase):
                # if this is an already-instantiated widget, just add the tab
                self.add_tab(tab_name, tab_ctrl)
                self._tab_state.append(tab_ctrl.layout)
            elif isinstance(tab_ctrl, tuple):
                # if we're doing lazy loading, add a lazy-load tab
                self._add_lazy_tab(tab_name, tab_ctrl)
        if self._tab_lazy_load:
            # Make sure content is loaded for tab 0
            self._load_tab(0)
    self.tab.observe(self._on_select_tab, names="selected_index")

