def _print_bytes(bytes_array: bytes):
    """Print byte array as string or hex."""
    enc_results = _get_byte_encoding(bytes_array)
    if enc_results.encoding_type != "binary":
        print(enc_results.decoded_string)

    else:
        print("Could not decode bytes to string. Hashes:")
        print(get_hashes(_binary_to_bytesio(bytes_array)))
        print(enc_results.printable_bytes)

def _get_byte_encoding(bytes_array: bytes) -> BinaryRecord:
    """
    Return encoding type and decoded result.

    Decoded result is list of hex bytes in the case that the decoded
    result is not a string
    """
    result_rec = _empty_binary_rec()
    printable_bytes = _as_byte_string(bytes_array)
    if _GET_UTF16():  # type: ignore
        try:
            # Difficult to tell the difference between a real unicode string
            # and a binary string that happens to decode to a utf-16 string.
            # So we don't do this unless instructed to
            decoded_string = bytes_array.decode("utf-16")
            return result_rec._replace(
                decoded_string=decoded_string,
                encoding_type="utf-16",
                printable_bytes=printable_bytes,
            )
        except UnicodeDecodeError:
            pass
    try:
        decoded_string = bytes_array.decode("utf-8")
        return result_rec._replace(
            decoded_string=decoded_string,
            encoding_type="utf-8",
            printable_bytes=printable_bytes,
        )
    except UnicodeDecodeError:
        pass

    return result_rec._replace(encoding_type="binary", printable_bytes=printable_bytes)

def _binary_to_bytesio(binary: Union[bytes, io.BytesIO]) -> memoryview:
    if isinstance(binary, io.BytesIO):
        return binary.getbuffer()
    return io.BytesIO(binary).getbuffer()

def _extract_event(message_dict: Mapping[str, Any]) -> Tuple[str, Mapping[str, Any]]:
    """
    Assemble discrete messages sharing the same message Id into a single event.

    Parameters
    ----------
    message_dict : Mapping[str, Any]
        the input dictionary

    Returns
    -------
    Tuple[str, Mapping[str, Any]
        the assembled message type and contents

    """
    # Handle process executions specially
    if "SYSCALL" in message_dict and "EXECVE" in message_dict:
        proc_create_dict: Dict[str, Any] = {}
        for mssg_type in ["SYSCALL", "CWD", "EXECVE", "PROCTITLE"]:
            if mssg_type not in message_dict or mssg_type not in _FIELD_DEFS:
                continue
            _extract_mssg_value(mssg_type, message_dict, proc_create_dict)

            if mssg_type == "EXECVE":
                args = int(proc_create_dict.get("argc", 1))
                arg_strs = [
                    proc_create_dict.get(f"a{arg_idx}", "") for arg_idx in range(args)
                ]
                proc_create_dict["cmdline"] = " ".join(arg_strs)
        return "SYSCALL_EXECVE", proc_create_dict

    event_dict: Dict[str, Any] = {}
    for mssg_type, _ in message_dict.items():
        if mssg_type in _FIELD_DEFS:
            _extract_mssg_value(mssg_type, message_dict, event_dict)
        else:
            # We don't check for duplicated keys here - if
            # there are multiple messages with the same key, the
            # last one will overwrite the previous value
            event_dict.update(message_dict[mssg_type])
    return list(message_dict.keys())[0], event_dict

def _check_decode_url(self, match_str, rgx_def, match_pos, iocs_found):
    """Get any other IoCs from decoded URL."""
    decoded_url = unquote(match_str)
    for url_match in rgx_def.comp_regex.finditer(decoded_url, match_pos):
        if url_match is not None:
            self._add_highest_pri_match(iocs_found, url_match.group(), rgx_def)
            self._add_highest_pri_match(
                iocs_found,
                url_match.groupdict()["host"],
                self._content_df_regex["dns"],
            )

