def _remove_col_prefix(data: pd.DataFrame, prefix: str) -> Dict[str, str]:
    """Return a mapping of column stems and columns with `prefix`."""
    return {
        col.replace(prefix, ""): col for col in data.columns if col.startswith(prefix)
    }

def __str__(self):
    """Return string representation of object properties."""
    str_props = [f"{prop}: {val}" for prop, val in self._source_data.items()]

    if self.entities:
        str_entities = [str(ent).replace("\n", ", ") for ent in self.entities]
        str_props += str_entities
    return "\n".join(str_props)

def __repr__(self) -> str:
    """Return repr of item."""
    if self.properties:
        params = ", ".join(
            [f"{name}={val}" for name, val in self.properties.items()]
        )
        if len(params) > 80:
            params = params[:80] + "..."
        return f"{self.__class__.__name__}({params})"
    return f"{self.__class__.__name__}()"

def to_html(self, show_entities=False) -> str:
    """Return the item as HTML string."""
    if self.properties:
        start = self.properties.get(
            "StartTimeUtc", self.properties.get("StartTime", "no timestamp")
        )
        name = self.properties.get(
            "AlertDisplayName",
            self.properties.get("DisplayName", "no alert name"),
        )
        entity = self.properties.get("CompromisedEntity", "unknown")
        title = f"""
        <h3>Alert: '{name}'</h3>
        <b>Alert_time:</b> {start},
        <b>Compr_entity:</b> {entity},
        <b>Alert_id:</b> self.properties['SystemAlertId']
        """
    else:
        title = "Alert has no data."
    return title + super().to_html(show_entities)

def to_html(self, show_entities: bool = False) -> str:
    """Return the item as HTML string."""
    html_doc = pd.DataFrame(self._source_data).to_html()

    if self._source_data is not None and "ExtendedProperties" in self._source_data:
        ext_prop_title = "<br/><h3>ExtendedProperties:</h3>"
        ext_prop_html = pd.DataFrame(
            pd.Series(self._source_data["ExtendedProperties"])
        ).to_html()
        html_doc = html_doc + ext_prop_title + ext_prop_html

    if show_entities and self.entities:
        entity_title = "<br/><h3>Entities:</h3><br/>"
        entity_html = "<br/>".join(
            [self._format_entity(ent) for ent in self.entities]
        )
        html_doc = html_doc + entity_title + entity_html
    else:
        e_counts = Counter([ent["Type"] for ent in self.entities])
        e_counts_str = ", ".join([f"{e}: {c}" for e, c in e_counts.items()])
        html_doc = html_doc + f"<h3>Entity counts: </h3>{e_counts_str}"
    return html_doc

def _format_entity(entity):
    str_entity = str(entity)
    if str_entity:
        str_entity = str_entity.replace("\n", ", ")
    return html.escape(str_entity)

def _find_os_family(self):
    """Return OSFamily and path separator to use from entities or file paths."""
    self.path_separator = "\\"
    self.os_family = "Windows"

    # Use OSFamily if any entities have this property set
    os_family_entities = [e for e in self.entities if "OSFamily" in e]
    if os_family_entities:
        for os_entity in os_family_entities:
            if os_entity["OSFamily"] == "Linux":
                self.os_family = "Linux"
                self.path_separator = "/"
                break
    else:
        # Otherwise try to infer from the file paths
        files = [e for e in self.entities if e["Type"] == "file"]
        if files:
            for file in files:
                if "Directory" in file and "/" in file["Directory"]:
                    self.os_family = "Linux"
                    self.path_separator = "/"
                    break
        else:
            for proc in [
                e
                for e in self.entities
                if e["Type"] == "process" and "ImageFile" in e
            ]:
                file = proc["ImageFile"]
                if "Directory" in file and "/" in file["Directory"]:
                    self.os_family = "Linux"
                    self.path_separator = "/"
                    break

def __init__(self, src_row: pd.Series = None):
    """Instantiate a security alert from a pandas Series."""
    super().__init__(src_row=src_row)

    # add entities to dictionary to remove dups
    self._src_entities: Dict[int, Entity] = {}

    self.extended_properties: Dict[str, Any] = {}
    if src_row is not None:
        if "Entities" in src_row:
            self._extract_entities(src_row)

        if "ExtendedProperties" in src_row:
            if isinstance(src_row.ExtendedProperties, dict):
                self.extended_properties = src_row.ExtendedProperties
            elif isinstance(src_row.ExtendedProperties, str):
                try:
                    self.extended_properties = json.loads(
                        src_row.ExtendedProperties
                    )
                except JSONDecodeError:
                    pass
    self._find_os_family()

def _find_graph_node(nx_graph, node_type, target_name):
    """Find a node with a given name and type."""
    node_prefix = f"{node_type}: {target_name}"
    nodes = [
        n
        for (n, n_type) in nx.get_node_attributes(nx_graph, "entitytype").items()
        if n_type == node_type and n.startswith(node_prefix)
    ]
    if nodes:
        return nodes[0]
    return None

def _get_name_and_description(entity, os_family="Windows"):
    """Get name and description for entity."""
    e_name = None
    e_description = None

    if entity["Type"] == "host":
        e_name, e_description = _get_host_name_desc(entity, os_family)
    elif entity["Type"] == "account":
        e_name, e_description = _get_account_name_desc(entity)
    elif entity["Type"] == "host-logon-session":
        e_name = "host-logon-session"
        e_description = f'Logon session {entity["SessionId"]}\n'
        e_description = e_description + f'(Start time: {entity["StartTimeUtc"]}'
    elif entity["Type"] == "process":
        e_name, e_description = _get_process_name_desc(entity)
    elif entity["Type"] == "file":
        e_name, e_description = _get_file_name_desc(entity)
    elif entity["Type"] in ["ip", "ipaddress"]:
        e_name, e_description = _get_ip_name_desc(entity)
    elif entity["Type"] == "dns":
        e_name = f"{entity['Type']}: {entity['DomainName']}"
        e_description = e_name
    else:
        # Any other type of entity
        e_name, e_description = _get_other_name_desc(entity)

    return e_name, e_description

def _get_other_name_desc(entity):
    if "Name" in entity:
        e_name = entity["Name"]
        e_name = f"{entity['Type']}: {e_name}"
    else:
        e_name = entity["Type"]

    if isinstance(entity, Entity):
        ent_props = entity.properties
    elif isinstance(entity, dict):
        ent_props = entity
    else:
        ent_props = {"unknown": None}

    # Nasty dict comprehension to join all other items in the
    # dictionary into a string
    e_properties = "\n".join(
        {
            f"{k}:{v}"
            for (k, v) in ent_props.items()
            if (k not in ("Type", "Name") and isinstance(v, str))
        }
    )
    e_description = f"{e_name}\n{e_properties})"
    return e_name, e_description

def _get_ip_name_desc(entity):
    e_name = entity["Address"]
    e_name = f"{entity['Type']}: {e_name}"
    if "Location" in entity and entity["Location"]:
        e_description = (
            f"{e_name}\nc={entity['Location']['CountryCode']}, "
            f"st={entity['Location']['State']}, city={entity['Location']['City']}"
        )
    else:
        e_description = e_name
    return e_name, e_description

def _get_account_name_desc(entity):
    e_dom = entity["NTDomain"]
    e_dom = e_dom + "\\" if e_dom else ""
    e_name = e_dom + (
        entity["Name"] or entity["AadUserId"] or entity["DisplayName"] or "unknown"
    )
    e_name = f"{entity.Type}: {e_name}"
    if "IsDomainJoined" in entity:
        domain_joined = entity["IsDomainJoined"]
    else:
        domain_joined = "false"
    if "LogonId" in entity:
        e_description = f"{e_name}\n(LogonId: {entity.LogonId},"
        e_description = e_description + f" Domain-joined: {domain_joined})"
    else:
        e_description = f"{e_name}\n(Domain-joined: {domain_joined})"
    return e_name, e_description

def _get_host_name_desc(entity, os_family):
    if "DnsDomain" in entity and is_not_empty(entity["DnsDomain"]):
        e_name = f"{entity.HostName}.{entity.DnsDomain}"
    elif "NTDomain" in entity and is_not_empty(entity["NTDomain"]):
        e_name = f"{entity.NTDomain}/{entity.HostName}"
    else:
        e_name = entity["HostName"]
    e_name = f"{entity.Type}: {e_name}"

    if "IsDomainJoined" in entity:
        domain_joined = entity["IsDomainJoined"]
    else:
        domain_joined = "false"
    if "OSFamily" in entity:
        os_family = entity["OSFamily"]
    e_description = f"{e_name}\n({os_family}, Domain-joined: {domain_joined})"

    return e_name, e_description
